        public DataSet OpenDataSet(string strFireQry)
        {
            DataSet ds = new DataSet();
            try
            {
                Connection con = new Connection();
                try
                {
                    con.OpenConection();
                    ds = con.ReturnDataSet(strFireQry);
                    con.CloseConnection();
                    return ds;
                }
                catch (Exception e)
                {
                    con.DisposeConnection();
                    throw e;
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

