                strsql += "[Fmt_scripcd] ASC,";
                strsql += "[Fmt_Type] ASC)";
                strsql += ")";
                ExecuteSQLTmp(strsql, objConnectionTmp);
            }

            dblHairCut = 0;
            Boolean blnBSE = false;
            Boolean blnNSE = false;
