                {
                    StrSql += " order by Case left(se_stlmnt,1) when 'B' then 0 else 1 end";
                }
                else if (strClgHs == "N")
                {
                    StrSql += " order by Case left(se_stlmnt,1) when 'N' then 0 else 1 end";
                }
                DsInterOP = OpenDataSet(StrSql);
                if (DsInterOP.Tables[0].Rows.Count == 0)
                    strData = strStlmnt + ",";
                else
