        public dynamic ExecuteCommonSP(string Str_SPname, Dictionary<string, string> dict_Param, SqlTransaction myTrans = null)
        {
            try
            {
                SqlConnection con = new SqlConnection();
                using (var db = new DataContext())
                {
                    con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                    if (con.State == ConnectionState.Closed)
                    {
                        con.Open();
                    }
                }
                SqlCommand MyCmd = new SqlCommand();
                SqlDataAdapter MyAdapter = new SqlDataAdapter();
                DataSet MyDataSet = new DataSet();
                MyCmd.Connection = con;
                MyCmd.CommandTimeout = 0;
                MyCmd.CommandText = Str_SPname;
                MyCmd.CommandType = CommandType.StoredProcedure;
                foreach (KeyValuePair<string, string> pair in dict_Param)
                {
                    MyCmd.Parameters.AddWithValue(pair.Key, pair.Value);
                }
                if (!(myTrans == null))
                    MyCmd.Transaction = myTrans;

                MyAdapter.SelectCommand = MyCmd;
                MyAdapter.Fill(MyDataSet);
                //MyCmd.ExecuteNonQuery();
                MyCmd.Dispose();
                MyAdapter.Dispose();
                return MyDataSet;
            }
            catch (Exception ex)
            {
                throw ex;
            }
            return null;
        }
