        }

        public string mfnFormatdate(string strDate, eNewDateformat eFormat)
        {
            string strFormatTemp;
            int intSeperatorPos;
            string strSeperator;

            strDate = strDate.Trim();
            if (Strings.InStr(1, strDate, ":") > 0)
            {
                strDate = Strings.Left(strDate, 10);
            }
            strFormatTemp = "XXXXXXXXXXX";
            switch (eFormat)
            {
                case eNewDateformat.EDATABASE:
                    strSeperator = "/";
                    intSeperatorPos = -1;
                    do
                    {
                        switch (strSeperator)
                        {
                            case "/":
                                intSeperatorPos = Strings.InStr(1, strDate, strSeperator);
                                if (intSeperatorPos <= 0)
                                {
                                    strSeperator = "-";
                                }
                                break;
                            case "-":
                                intSeperatorPos = Strings.InStr(1, strDate, strSeperator);
                                if (intSeperatorPos <= 0)
                                {
                                    strSeperator = " ";
                                }
                                break;
                            case " ":
                                intSeperatorPos = Strings.InStr(1, strDate, strSeperator);
                                if (intSeperatorPos <= 0)
                                {
                                    strSeperator = "#";
                                }
                                break;
                            case "#":
                                intSeperatorPos = Strings.InStr(1, strDate, strSeperator);
                                if (intSeperatorPos <= 0)
                                {
                                    strSeperator = ",";
                                }
                                break;
                            case ",":
                                intSeperatorPos = Strings.InStr(1, strDate, strSeperator);
                                if (intSeperatorPos <= 0)
                                {
                                    strSeperator = "*";
                                }
                                break;
                        }
                    }
                    while (strSeperator == "*" || intSeperatorPos < 0);
                    if (intSeperatorPos > 0)
                    {
                        intSeperatorPos = Strings.InStr(intSeperatorPos + 1, strDate, strSeperator);
                        if (intSeperatorPos > 0)
                        {
                            if (Strings.Len(strDate) == 6)
                            {
                                if (Information.IsNumeric(Strings.Left(strDate, 1)) && Information.IsNumeric(Strings.Mid(strDate, 3, 1)) && Information.IsNumeric(Strings.Right(strDate, 2)))
                                {
                                    strFormatTemp = mfnGetFullYear(Strings.Right(strDate, 2)) + "0" + Strings.Mid(strDate, 3, 1) + "0" + Strings.Left(strDate, 1);
                                }
                            }
                            else if (Strings.Len(strDate) == 7)
                            {
                                if (Strings.InStr(1, strDate, strSeperator) == 2)
                                {
                                    if (Information.IsNumeric(Strings.Left(strDate, 1)) && Information.IsNumeric(Strings.Mid(strDate, 3, 2)) && Information.IsNumeric(Strings.Right(strDate, 2)))
                                    {
                                        strFormatTemp = mfnGetFullYear(Strings.Right(strDate, 2)) + Strings.Mid(strDate, 3, 2) + "0" + Strings.Left(strDate, 1);
                                    }
                                }
                                else if (Strings.InStr(1, strDate, strSeperator) == 3)
                                {
                                    if (Information.IsNumeric(Strings.Left(strDate, 2)) && Information.IsNumeric(Strings.Mid(strDate, 4, 1)) && Information.IsNumeric(Strings.Right(strDate, 2)))
                                    {
                                        strFormatTemp = mfnGetFullYear(Strings.Right(strDate, 2)) + "0" + Strings.Mid(strDate, 4, 1) + Strings.Left(strDate, 2);
                                    }
                                }
                            }
                            else if (Strings.Len(strDate) == 8)
                            {
                                if (Strings.InStr(1, strDate, strSeperator) == 2)
                                {
                                    if (Strings.InStr(Strings.InStr(1, strDate, strSeperator) + 1, strDate, strSeperator) == 4)
                                    {
                                        if (Information.IsNumeric(Strings.Left(strDate, 1)) && Information.IsNumeric(Strings.Mid(strDate, 3, 1)) && Information.IsNumeric(Strings.Right(strDate, 4)))
                                        {
                                            strFormatTemp = Strings.Right(strDate, 4) + "0" + Strings.Mid(strDate, 4, 1) + "0" + Strings.Left(strDate, 1);
                                        }
                                    }
                                    else
                                    {
                                        strFormatTemp = mfnGetFullYear(Strings.Right(strDate, Strings.Len(strDate) - Strings.InStrRev(strDate, strSeperator))) + mfnGetMonthIndex(Strings.Mid(strDate, Strings.InStr(1, strDate, strSeperator) + 1, Strings.InStrRev(strDate, strSeperator) - Strings.InStr(1, strDate, strSeperator) - 1)) + Strings.Format(Convert.ToInt32(Strings.Left(strDate, Strings.InStr(1, strDate, strSeperator) - 1)), "00");
                                    }
                                }
                                else if (Strings.InStr(1, strDate, strSeperator) == 3)
                                {
                                    if (Information.IsNumeric(Strings.Left(strDate, 2)) && Information.IsNumeric(Strings.Mid(strDate, 4, 2)) && Information.IsNumeric(Strings.Right(strDate, 2)))
                                    {
                                        strFormatTemp = mfnGetFullYear(Strings.Right(strDate, 2)) + Strings.Mid(strDate, 4, 2) + Strings.Left(strDate, 2);
                                    }
                                }
                            }
                            else if (Strings.Len(strDate) == 9)
                            {
                                if (Strings.InStr(1, strDate, strSeperator) == 2)
                                {
                                    if (Information.IsNumeric(Strings.Left(strDate, 1)) && Information.IsNumeric(Strings.Mid(strDate, 3, 2)) && Information.IsNumeric(Strings.Right(strDate, 4)))
                                    {
                                        strFormatTemp = Strings.Right(strDate, 4) + Strings.Mid(strDate, 3, 2) + "0" + Strings.Left(strDate, 1);
                                    }
                                    else
                                    {
                                        strFormatTemp = mfnGetFullYear(Strings.Right(strDate, Strings.Len(strDate) - Strings.InStrRev(strDate, strSeperator))) + mfnGetMonthIndex(Strings.Mid(strDate, Strings.InStr(1, strDate, strSeperator) + 1, Strings.InStrRev(strDate, strSeperator) - Strings.InStr(1, strDate, strSeperator) - 1)) + Strings.Format(Convert.ToInt32(Strings.Left(strDate, Strings.InStr(1, strDate, strSeperator) - 1)), "00");
                                    }
                                }
                                else
                                {
                                    if (Strings.InStr(Strings.InStr(1, strDate, strSeperator) + 1, strDate, strSeperator) == 5)
                                    {
                                        if (Information.IsNumeric(Strings.Left(strDate, 2)) && Information.IsNumeric(Strings.Mid(strDate, 4, 1)) && Information.IsNumeric(Strings.Right(strDate, 4)))
                                        {
                                            strFormatTemp = Strings.Right(strDate, 4) + "0" + Strings.Mid(strDate, 4, 1) + Strings.Left(strDate, 2);
                                        }
                                    }
                                    else if (Strings.InStr(Strings.InStr(1, strDate, strSeperator) + 1, strDate, strSeperator) == 6)
                                    {
                                        if (Information.IsNumeric(Strings.Left(strDate, 2)) && Information.IsNumeric(Strings.Mid(strDate, 4, 2)) && Information.IsNumeric(Strings.Right(strDate, 3)))
                                        {
                                            strFormatTemp = mfnGetFullYear(Strings.Right(strDate, 3)) + Strings.Mid(strDate, 4, 2) + Strings.Left(strDate, 2);
                                        }
                                    }
                                    else
                                    {
                                        strFormatTemp = mfnGetFullYear(Strings.Right(strDate, Strings.Len(strDate) - Strings.InStrRev(strDate, strSeperator))) + mfnGetMonthIndex(Strings.Mid(strDate, Strings.InStr(1, strDate, strSeperator) + 1, Strings.InStrRev(strDate, strSeperator) - Strings.InStr(1, strDate, strSeperator) - 1)) + Strings.Format(Convert.ToInt32(Strings.Left(strDate, Strings.InStr(1, strDate, strSeperator) - 1)), "00");
                                    }
                                }
                            }
                            else if (Strings.Len(strDate) == 10)
                            {
                                if (Strings.InStr(1, strDate, strSeperator) == 3)
                                {
                                    if (Information.IsNumeric(Strings.Left(strDate, 2)) && Information.IsNumeric(Strings.Mid(strDate, 4, 2)) && Information.IsNumeric(Strings.Right(strDate, 4)))
                                    {
                                        strFormatTemp = Strings.Right(strDate, 4) + Strings.Mid(strDate, 4, 2) + Strings.Left(strDate, 2);
                                    }
                                    else
                                    {
                                        strFormatTemp = mfnGetFullYear(Strings.Right(strDate, Strings.Len(strDate) - Strings.InStrRev(strDate, strSeperator))) + mfnGetMonthIndex(Strings.Mid(strDate, Strings.InStr(1, strDate, strSeperator) + 1, Strings.InStrRev(strDate, strSeperator) - Strings.InStr(1, strDate, strSeperator) - 1)) + Strings.Format(Convert.ToInt32(Strings.Left(strDate, Strings.InStr(1, strDate, strSeperator) - 1)), "00");
                                    }
                                }
                                else
                                {
                                    strFormatTemp = mfnGetFullYear(Strings.Right(strDate, Strings.Len(strDate) - Strings.InStrRev(strDate, strSeperator))) + mfnGetMonthIndex(Strings.Mid(strDate, Strings.InStr(1, strDate, strSeperator) + 1, Strings.InStrRev(strDate, strSeperator) - Strings.InStr(1, strDate, strSeperator) - 1)) + Strings.Format(Convert.ToInt32(Strings.Left(strDate, Strings.InStr(1, strDate, strSeperator) - 1)), "00");
                                }
                            }
                            else if (Strings.Len(strDate) >= 11)
                            {
                                strFormatTemp = mfnGetFullYear(Strings.Right(strDate, Strings.Len(strDate) - Strings.InStrRev(strDate, strSeperator))) + mfnGetMonthIndex(Strings.Mid(strDate, Strings.InStr(1, strDate, strSeperator) + 1, Strings.InStrRev(strDate, strSeperator) - Strings.InStr(1, strDate, strSeperator) - 1)) + Strings.Format(Convert.ToInt32(Strings.Left(strDate, Strings.InStr(1, strDate, strSeperator) - 1)), "00");
                            }
                        }
                    }
                    else if (Strings.Len(strDate) == 8)
                    {
                        strFormatTemp = strDate;
                    }
                    if (Information.IsNumeric(strFormatTemp) == false)
                    {
                        strFormatTemp = "XXXXXXXXXXX";
                    }
                    if (Information.IsDate(Strings.Left(strFormatTemp, 4) + "/" + Strings.Mid(strFormatTemp, 5, 2) + "/" + Strings.Right(strFormatTemp, 2)) == false || Conversion.Val(Strings.Mid(strFormatTemp, 5, 2)) < 1 || Conversion.Val(Strings.Mid(strFormatTemp, 5, 2)) > 12)
                    {
                        strFormatTemp = "XXXXXXXXXXX";
                    }
                    break;
                case eNewDateformat.eShortDate:
                    strFormatTemp = mfnFormatdate(strDate, eNewDateformat.EDATABASE);
                    if (Information.IsNumeric(strFormatTemp))
                    {
                        strFormatTemp = Strings.Right(strFormatTemp, 2) + "/" + Strings.Mid(strFormatTemp, 5, 2) + "/" + Strings.Left(strFormatTemp, 4);
                    }
                    else
                    {
                        strFormatTemp = "XXXXXXXXXXX";
                    }
                    break;
                case eNewDateformat.eMiniDate:
                    strFormatTemp = mfnFormatdate(strDate, eNewDateformat.EDATABASE);
                    if (Information.IsNumeric(strFormatTemp))
                    {
                        strFormatTemp = Strings.Right(strFormatTemp, 2) + "/" + Strings.Mid(strFormatTemp, 5, 2) + "/" + Strings.Mid(strFormatTemp, 3, 2);
                    }
                    else
                    {
                        strFormatTemp = "XXXXXXXXXXX";
                    }
                    break;
                case eNewDateformat.eLongDate:
                    strFormatTemp = mfnFormatdate(strDate, eNewDateformat.EDATABASE);
                    if (Information.IsNumeric(strFormatTemp))
                    {
                        if (Convert.ToInt32(Strings.Mid(strFormatTemp, 5, 2)) > 0 && Convert.ToInt32(Strings.Mid(strFormatTemp, 5, 2)) <= 12 && Information.IsDate(Strings.Left(strFormatTemp, 4) + "/" + Strings.Mid(strFormatTemp, 5, 2) + "/" + Strings.Right(strFormatTemp, 2)))
                        {
                            strFormatTemp = Strings.Format(Convert.ToInt32(Strings.Right(strFormatTemp, 2)), "00") + " " + mfnGetMonthName(Convert.ToInt32(Strings.Mid(strFormatTemp, 5, 2)), eMonthFormat.eLongMonth) + "," + Strings.Left(strFormatTemp, 4);
                        }
                        else
                        {
                            strFormatTemp = "XXXXXXXXXXX";
                        }
                    }
                    else
                    {
                        strFormatTemp = "XXXXXXXXXXX";
                    }
                    break;
            }
            return strFormatTemp;
        }

        public string mfnGetFullYear(string strvalue)
        {
            string strCentury;
            strvalue = strvalue.Trim();
            if (Conversion.Val(Strings.Right(strvalue, 2)) > 90)
            {
                strCentury = "19";
            }
            else
            {
                strCentury = "20";
            }
            if (Strings.Len(strvalue) == 4)
            {
                return strvalue;
            }
            else if (Strings.Len(strvalue) == 3)
            {
                return Strings.Left(strvalue, 1) + strvalue;
            }
            else if (Strings.Len(strvalue) == 2)
            {
                return strCentury + strvalue;
            }
            else if (Strings.Len(strvalue) == 1)
            {
                return strCentury + "0" + strvalue;
            }
            else
            {
                return "2000";
            }
        }

