        public void CheckSP(string strParamCode, SqlConnection conn = null)
        {
            try
            {
                string strsql = "";
                string strPath = Path.Combine(Directory.GetCurrentDirectory(), "SQL", strParamCode + ".sql");

                if (!File.Exists(strPath))
                {
                    return;
                }

                DateTime LastWriteTime = File.GetLastWriteTime(strPath);
                //removing milliseconds for comparision
                LastWriteTime = new DateTime(LastWriteTime.Year, LastWriteTime.Month, LastWriteTime.Day, LastWriteTime.Hour, LastWriteTime.Minute, LastWriteTime.Second);

                string strParamDesc = strParamCode.Trim() + " SP";
                strParamCode = strParamCode.Trim() + "SP";
                string strDbDateTime = "";
                string strMode = "";

                var db = new DataContext();
                //using SqlConnection sqlCon = conn ?? new SqlConnection(db.Database.GetDbConnection().ConnectionString);
                SqlConnection sqlCon = conn ?? new SqlConnection(db.Database.GetDbConnection().ConnectionString);
                bool blnShouldClose = false;

                if (conn == null)
                {
                    blnShouldClose = true;
                }
                if (sqlCon.State == ConnectionState.Closed)
                {
                    sqlCon.Open();
                }

                if (fnchkTable("Webparameter", sqlCon))
                {
                    strsql = "select sp_sysvalue from webparameter where sp_parmcd='" + strParamCode + "'";
                    DataTable dt = OpenDataTable(strsql, sqlCon);

                    if (dt.Rows.Count > 0)
                    {
                        strDbDateTime = dt.Rows[0]["sp_sysvalue"].ToString().Trim();
                        DateTime dtDb;
                        if (DateTime.TryParseExact(strDbDateTime, "yyyyMMddHHmmss", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out dtDb))
                        {
                            if (LastWriteTime > dtDb)
                            {
                                strMode = "U";
                            }
                        }
                    }
                    else
                    {
                        strMode = "I";
                    }
                }
                else
                {
                    strMode = "N";
                }

                if (strMode != "")
                {
                    // Read the content of the .sql file
                    string sqlScript = "";

                    using (StreamReader reader = new StreamReader(strPath, Encoding.UTF8))
                    {
                        string strFileText = reader.ReadToEnd();
                        //string strEnc = Convert.ToBase64String(EncryptStringToBytes_Aes(strFileText, Encoding.UTF8.GetBytes("5F4E3D2C1B0A9876"), Encoding.UTF8.GetBytes("7A6B5C4D3E2F1A09")));
                        sqlScript = DecryptStringFromBytes_Aes(Convert.FromBase64String(strFileText), Encoding.UTF8.GetBytes("5F4E3D2C1B0A9876"), Encoding.UTF8.GetBytes("7A6B5C4D3E2F1A09"));
                    }
                    string[] batches = Regex.Split(sqlScript, @"^\s*GO\s*$", RegexOptions.Multiline);

                    foreach (string batch in batches)
                    {
                        if (batch.Trim() != "")
                        {
                            try
                            {
                                using SqlCommand command = new SqlCommand(batch, sqlCon);
                                command.ExecuteNonQuery();
                            }
                            catch (Exception ex)
                            {
                                continue;
                            }
                        }
                    }

                    if (strMode == "I")
                    {
                        strsql = "Insert into webparameter values ('" + strParamCode + "', '" + strParamDesc + "', '" + LastWriteTime.ToString("yyyyMMddHHmmss") + "')";
                        ExecuteSQL(strsql, sqlCon);
                    }
                    else if (strMode == "U")
                    {
                        strsql = "update webparameter set sp_sysvalue='" + LastWriteTime.ToString("yyyyMMddHHmmss") + "' where sp_parmcd='" + strParamCode + "'";
                        ExecuteSQL(strsql, sqlCon);
                    }
                }

                if (blnShouldClose)
                {
                    sqlCon.Dispose();
                }
                return;
            }
            catch (Exception ex)
            {
                return;
            }
        }

        public static byte[] EncryptStringToBytes_Aes(string plainText, byte[] Key, byte[] IV)
        {
            // Check arguments.
            if (plainText == null || plainText.Length <= 0)
                throw new ArgumentNullException("plainText");
            if (Key == null || Key.Length <= 0)
                throw new ArgumentNullException("Key");
            if (IV == null || IV.Length <= 0)
                throw new ArgumentNullException("IV");

            byte[] encrypted;

            // Create an Aes object with the specified key and IV.
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = Key;
                aesAlg.IV = IV;

                // Create an encryptor to perform the stream transform.
                ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);

                // Create the streams used for encryption.
                using (MemoryStream msEncrypt = new MemoryStream())
                {
                    using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        using (StreamWriter swEncrypt = new StreamWriter(csEncrypt))
                        {
                            //Write all data to the stream.
                            swEncrypt.Write(plainText);
                        }
                        encrypted = msEncrypt.ToArray();
                    }
                }
            }

            // Return the encrypted bytes from the memory stream.
            return encrypted;
        }

        public static string DecryptStringFromBytes_Aes(byte[] cipherText, byte[] Key, byte[] IV)
        {
            // Check arguments.
            if (cipherText == null || cipherText.Length <= 0)
                throw new ArgumentNullException("cipherText");
            if (Key == null || Key.Length <= 0)
                throw new ArgumentNullException("Key");
            if (IV == null || IV.Length <= 0)
                throw new ArgumentNullException("IV");

            // Declare the string used to hold the decrypted text.
            string plaintext = null;

            // Create an Aes object with the specified key and IV.
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = Key;
                aesAlg.IV = IV;

                // Create a decryptor to perform the stream transform.
                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                // Create the streams used for decryption.
                using (MemoryStream msDecrypt = new MemoryStream(cipherText))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            // Read the decrypted bytes from the decrypting stream and place them in a string.
                            plaintext = srDecrypt.ReadToEnd();
                        }
                    }
                }
            }

            return plaintext;
        }

