            string strsql = "update tbl_GenericAPIDebugLog set ResponseString = @ResponseString, ExceptionMessage = @ExceptionMessage";
            if (!string.IsNullOrWhiteSpace(strRequestUniqueID))
            {
                strsql += ", RequestUniqueID = @RequestUniqueID";
            }
            strsql += " where SerialNo = @SerialNo";
            using (SqlCommand command = new SqlCommand(strsql, ObjConnection))
            {
                command.Parameters.AddWithValue("@ResponseString", strResponse);
                command.Parameters.AddWithValue("@ExceptionMessage", strException);
                if (!string.IsNullOrWhiteSpace(strRequestUniqueID))
                {
                    command.Parameters.AddWithValue("@RequestUniqueID", strRequestUniqueID);
                }
                command.Parameters.AddWithValue("@SerialNo", srNo);

                command.ExecuteNonQuery();
            }
        }

        public string MaskedIdentityNumber(string maskString, int startFrom, int endTo)
        {
            if (!string.IsNullOrEmpty(maskString))
            {
                int lastOpr = startFrom + endTo;
                if (maskString.Trim().Length > lastOpr)
                {
                    var aStringBuilder = new StringBuilder(maskString.Trim());
                    aStringBuilder.Remove(startFrom, maskString.Length - lastOpr);
                    aStringBuilder.Insert(startFrom, "X", maskString.Length - lastOpr);
                    maskString = aStringBuilder.ToString();
                }
            }
            return maskString;
        }


