        public string GetConnectionStr()
        {
            try
            {
                string StrConn = ConfigurationManager.GetConnectionString("DefaultConnection");
                if (StrConn.Contains("EPWD"))
                {
                    UtilityCommon objUtility = new UtilityCommon();
                    string epwd = StrConn.Split("EPWD=")[1].Split(";")[0];
                    string pwd = "";
                    if (!string.IsNullOrWhiteSpace(epwd))
                    {
                        pwd = objUtility.Decrypt(epwd);
                        StrConn = StrConn.Replace(epwd, pwd);
                    }
                    StrConn = StrConn.Replace("EPWD", "Pwd");
                }
                return StrConn;
            }
            catch (Exception ex) { }

            return "";
        }

        public DataTable TradeMobileSendOTP(string clientCd, string Product, string Mode, string role)
        {
            try
            {
                string strsql = "";
                DataTable dtTable = new DataTable();
                dtTable.Columns.Add("Status", typeof(string));
                dtTable.Columns.Add("Message", typeof(string));
                DataRow dr = dtTable.NewRow();
                SqlTransaction objTrans;
                var strSMSParamVal = new string[5];
                string strSMSParameter = "SMSUSERID/SMSPWD/SMSSENDER/SMSLENGTH/SMSLINK";
                string strvalue = string.Empty;
                string strPass = "";
                string strMsgTxt = "";
                string strUser = "";
                string strMobile = "";
                string strFromNo1 = "";
                string strFromNo2 = "";
                string strresponse = "", strMobileNo = "";
                int intOTPValidTime = 5; //In Minutes
                bool blnOTP = false;

                CreateOTPMasterTable();

                string chars1 = "1234567890";
                char[] stringChars1 = new char[4];

                Random random1 = new Random();

                for (int i = 0; i < stringChars1.Length; i++)
                {
                    stringChars1[i] = chars1[random1.Next(chars1.Length)];
                }

                string strSotp = new String(stringChars1);

                string connetionString = GetConnectionStr();
                using (SqlConnection objConnection = new SqlConnection(connetionString))
                {
                    objConnection.Open();
                    //objTrans = objConnection.BeginTransaction();
                    SqlCommand cmd = objConnection.CreateCommand();
                    //cmd.Transaction = objTrans;
                    SqlDataAdapter sqlDtAdap = new SqlDataAdapter();
                    SqlCommandBuilder sqlCmdBld = new SqlCommandBuilder(sqlDtAdap);

                    if (string.IsNullOrEmpty(clientCd.Trim()))
                    {
                        dtTable.Rows.Add("N", "Client Not Found");
                        return dtTable;
                    }
                    clientCd = clientCd.Trim().Replace("'", "");
                    if (!string.IsNullOrEmpty(clientCd))
                    {
                        if (role == "CrossNet" || role == "EstroNet" || role == "Branch")
                        {
                            string Strsql = "";
                            if (role == "Branch")
                            {
                                Strsql = "select um_user_id, um_add2 um_mobile  From User_master where um_user_id = '" + clientCd + "'";
                            }
                            else
                            {
                                Strsql = "select um_user_id, um_dept um_mobile  From User_master where um_user_id = '" + clientCd + "'";
                            }
                            DataSet ds = OpenDataSet(Strsql);
                            if (ds.Tables[0].Rows.Count == 0)
                            {
                                dtTable.Rows.Add("N", "User not found!");
                                return dtTable;
                            }
                            if (ds.Tables[0].Rows[0]["um_mobile"].ToString().Trim() == "" || !Regex.IsMatch(ds.Tables[0].Rows[0]["um_mobile"].ToString().Trim(), @"^\d{10,}$") || ds.Tables[0].Rows[0]["um_mobile"].ToString().Trim().Length < 10)
                            {
                                dtTable.Rows.Add("N", "Mobile Number is not available");
                                return dtTable;
                            }
                            strMobileNo = Strings.Right(ds.Tables[0].Rows[0]["um_mobile"].ToString().Trim(), 10);
                            if (Mode == "FP")
                            {
                                strMsgTxt = fnFireQuery("sysparameter", "SP_SYSVALUE", "sp_parmcd", "SMSTWEBPWD", false);
                            }
                            else if (Mode == "2FA")
                            {
                                strMsgTxt = fnFireQuery("sysparameter", "SP_SYSVALUE", "sp_parmcd", "SMS2FA", false);
                            }
                        }
                        else if (Convert.ToInt16(fnFireQuery("Client_master", "count(0)", "cm_cd", clientCd.Trim(), true)) > 0)
                        {
                            strMobileNo = fnFireQuery("Client_master", "cm_mobile", "cm_cd", clientCd.Trim(), true).Trim();
                            if (string.IsNullOrEmpty(strMobileNo.Trim()))
                            {
                                dtTable.Rows.Add("N", "Mobile Number is not registered with us");
                                return dtTable;
                            }
                            //strPass = fnFireQuery("Client_master", "cm_pwd", "cm_cd", clientCd.Trim(), true);
                            if (Product.Trim().ToUpper() == "CROSSWEB" || Product.Trim().ToUpper() == "ESTROWEB")
                            {
                                if (Mode == "FP")
                                {
                                    if (Convert.ToInt16(fnFireQuery("Webparameter", "count(0)", "sp_parmcd", "SMSGETPWD", true)) > 0)
                                    {
                                        strMsgTxt = fnFireQuery("Webparameter", "SP_SYSVALUE", "sp_parmcd", "SMSGETPWD", true);
                                    }
                                    else
                                    {
                                        strMsgTxt = "Client code <Client>, your OTP to Login in Tradeweb is : <OTP>";
                                    }
                                }
                                else if (Mode == "2FA")
                                {
                                    if (Convert.ToInt16(fnFireQuery("Webparameter", "count(0)", "sp_parmcd", "SMS2FA", true)) > 0)
                                    {
                                        strMsgTxt = fnFireQuery("Webparameter", "SP_SYSVALUE", "sp_parmcd", "SMS2FA", true);
                                    }
                                }
                            }
                            else
                            {
                                if (Mode == "FP")
                                {
                                    if (Convert.ToInt16(fnFireQuery("Sysparameter", "count(0)", "sp_parmcd", "SMSTWEBPWD", true)) > 0)
                                    {
                                        strMsgTxt = fnFireQuery("sysparameter", "SP_SYSVALUE", "sp_parmcd", "SMSTWEBPWD", true);
                                    }
                                    else if (Convert.ToInt16(fnFireQuery("Webparameter", "count(0)", "sp_parmcd", "SMSGETPWD", true)) > 0)
                                    {
                                        strMsgTxt = fnFireQuery("Webparameter", "SP_SYSVALUE", "sp_parmcd", "SMSGETPWD", true);
                                    }
                                    else
                                    {
                                        strMsgTxt = "Client code <Client>, your OTP to Login in Tradeweb is : <OTP>";
                                    }
                                }
                                else if (Mode == "2FA")
                                {
                                    if (Convert.ToInt16(fnFireQuery("Webparameter", "count(0)", "sp_parmcd", "SMS2FA", true)) > 0)
                                    {
                                        strMsgTxt = fnFireQuery("Webparameter", "SP_SYSVALUE", "sp_parmcd", "SMS2FA", true);
                                    }
                                }
                                else if (Mode == "FR")
                                {
                                    if (Convert.ToInt16(fnFireQuery("Webparameter", "count(0)", "sp_parmcd", "FundReqOTP", true)) > 0)
                                    {
                                        strMsgTxt = fnFireQuery("Webparameter", "SP_SYSVALUE", "sp_parmcd", "FundReqOTP", true);
                                    }
                                }
                            }
                        }
                        else
                        {
                            dtTable.Rows.Add("N", "Client Not Found");
                            return dtTable;
                        }


                        var sb = new StringBuilder();
                        sb = new StringBuilder(strMobileNo);
                        int i;
                        var loopTo = strMobileNo.Length - 3;
                        for (i = 2; i <= loopTo; i++)
                            sb[i] = 'x';
                        strMobile = sb.ToString();
                        sb = new StringBuilder(clientCd.Trim().ToUpper());
                        var loopTo1 = clientCd.Length - 1;
                        for (i = 1; i <= loopTo1; i++)
                            sb[i] = 'x';
                        strUser = sb.ToString();
                        strMsgTxt = strMsgTxt.Replace("<Client>", strUser);
                        strMsgTxt = strMsgTxt.Replace("<OTP>", strSotp);

                        strMsgTxt = strMsgTxt.Replace("<&>", "<~>");
                        strMsgTxt = strMsgTxt.Replace("&", "");
                        strMsgTxt = strMsgTxt.Replace("<~>", "&");

                        if (Product.Trim().ToUpper() == "CROSSWEB" || Product.Trim().ToUpper() == "ESTROWEB")
                        {
                            if (Convert.ToInt32(fnFireQueryTradeWeb("webparameter", "count(0)", "sp_parmcd", "SMSSETUP", true)) > 0)
                            {
                                strvalue = fnFireQueryTradeWeb("webparameter", "SP_SYSVALUE", "sp_parmcd", "SMSSETUP", true);
                                strSMSParamVal[0] = strvalue.Split('~')[1];
                                strSMSParamVal[1] = strvalue.Split('~')[2];
                                strSMSParamVal[2] = strvalue.Split('~')[3];
                                strSMSParamVal[3] = strvalue.Split('~')[4];
                                strSMSParamVal[4] = strvalue.Split('~')[0];
                            }
                        }
                        else
                        {
                            for (i = 0; i <= 4; i++)
                            {
                                strvalue = strSMSParameter.Split('/')[i];
                                strSMSParamVal[i] = fnFireQuery("sysparameter", "SP_SYSVALUE", "sp_parmcd", strvalue, true);
                            }
                        }

                        if (strSMSParamVal.All(string.IsNullOrEmpty))
                        {
                            dtTable.Rows.Add("N", "SMS Setting not present");
                            return dtTable;
                        }

                        string strURLLink = strSMSParamVal[4];

                        if (strURLLink.IndexOf("<USERID>") != -1 & !string.IsNullOrEmpty(strSMSParamVal[0].Trim()))
                        {
                            strURLLink = strURLLink.Replace("<USERID>", strSMSParamVal[0].Trim());
                        }
                        if (strURLLink.IndexOf("<PASSWORD>") != -1 & !string.IsNullOrEmpty(strSMSParamVal[1].Trim()))
                        {
                            strURLLink = strURLLink.Replace("<PASSWORD>", strSMSParamVal[1].Trim());
                        }
                        if (string.IsNullOrEmpty(strSMSParamVal[2].Trim()))
                        {
                            if (strURLLink.IndexOf("<SENDERID>") != -1)
                            {
                                strURLLink = strURLLink.Replace("<SENDERID>", strSMSParamVal[2].Trim());
                            }
                        }
                        else
                        {
                            strFromNo1 = strSMSParamVal[2].Trim();
                            if (strFromNo1.IndexOf("|") != -1)
                            {
                                strFromNo2 = strFromNo1.Split("|")[1];
                                strFromNo1 = strFromNo1.Split("|")[0];
                            }
                            else
                            {
                                strFromNo1 = Strings.Left(strFromNo1.Trim(), 10);
                                strFromNo2 = "";
                            }
                            if (strURLLink.IndexOf("<SENDERID>") != -1)
                            {
                                strURLLink = strURLLink.Replace("<SENDERID>", strSMSParamVal[2].Trim());
                            }
                            else if (strURLLink.IndexOf("<SENDERID1>") != -1 | strURLLink.IndexOf("<SENDERID2>") != -1)
                            {
                                strURLLink = strURLLink.Replace("<SENDERID1>", strFromNo1).Replace("<SENDERID2>", strFromNo2);
                            }
                        }
                        strURLLink = strURLLink.Replace("<MESSAGE>", strMsgTxt);

                        if (strURLLink.IndexOf("/opted.smsapi.org/v1.0.7/") != -1)
                        {
                            strURLLink = strURLLink.Replace("<MESSAGE>", strMsgTxt);
                        }

                        if (strURLLink.IndexOf("/174.143.34.193/") != -1)
                        {
                            if (strMsgTxt.Trim().Length > 160)
                            {
                                strURLLink = strURLLink + "&mt=4";
                            }
                            else
                            {
                                strURLLink = strURLLink + "&mt=0";
                            }
                            strURLLink = strURLLink + "&typeofmessage=1";
                        }

                        if (GetSysParmSt("SMSCOUNTRYCD", "") == "Y")
                        {
                            if (strMobileNo.Trim().Length == 10)
                            {
                                strMobileNo = "91" + strMobileNo;
                            }
                        }
                        else if (strMobileNo.Trim().Length > 10)
                        {
                            strMobileNo = Strings.Right(strMobileNo.Trim(), 10);
                        }
                        strURLLink = strURLLink.Replace("<CLIENTMOBILE>", strMobileNo.Trim());

                        if (strURLLink.IndexOf("myvaluefirst.com") != -1)
                        {
                            string strSENDER = "";
                            if (strSMSParamVal[2].Trim().IndexOf("|") != -1)
                            {
                                if (Strings.Left(strMobileNo.Trim(), 2) == "92" | Strings.Left(strMobileNo.Trim(), 2) == "93")
                                {
                                    strSENDER = strSMSParamVal[2].Trim().Split("|")[1];
                                }
                                else
                                {
                                    strSENDER = strSMSParamVal[2].Trim().Split("|")[0];
                                }
                            }
                            else
                            {
                                strSENDER = Strings.Left(strSMSParamVal[2].Trim(), 10);
                            }
                            strURLLink = strURLLink.Replace("<SENDERID3>", strSENDER);
                        }

                        if (GetWebParameter("SECURITYPROT").Trim() == "TLS12")
                        {
                            ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072;
                        }

                        string content = "";

                        var (Status, Message) = InsertOTP(clientCd, strSotp, strMobileNo, "MO", Product, Mode, intOTPValidTime, objConnection);
                        if (Status == "N")
                        {
                            dtTable.Rows.Add(Status, Message);
                            return dtTable;
                        }

                        try
                        {
                            HttpWebRequest http = (HttpWebRequest)WebRequest.Create(strURLLink);
                            ServicePointManager.Expect100Continue = true;
                            HttpWebResponse response = (HttpWebResponse)http.GetResponse();
                            var sr = new StreamReader(response.GetResponseStream());
                            content = sr.ReadToEnd();
                            strresponse = content;

                            if (response.StatusCode == HttpStatusCode.OK)
                            {
                                strresponse = "SMS Sent Successfully.";
                            }
                            else if (Strings.InStr(1, content, "<ERROR>") > 0)
                            {
                                if (Strings.InStr(1, strresponse, "<DESC>") > 0)
                                {
                                    strresponse = Strings.Mid(content, Strings.InStr(1, content, "<DESC>") + 6);
                                    strresponse = Strings.Left(content, Strings.InStr(1, content, "</DESC>") - 1);
                                }
                                else
                                {
                                    strresponse = "SMS Sent Successfully.";
                                }
                            }
                            else if (Strings.InStr(1, content, "\"error-status\":\"Success\"") > 0)
                            {
                                strresponse = "SMS Sent Successfully.";
                            }
                            else if (Strings.InStr(1, content, Strings.Trim(strMobileNo)) > 0)
                            {
                                strresponse = "Message Send Successfully.";
                            }
                            else if (Strings.InStr(1, content, "<sms>") > 0)
                            {
                                if (Strings.InStr(1, content, "-1") > 0)
                                {
                                    strresponse = "Message Sending Failed";
                                }
                                else if (Strings.InStr(1, Strings.UCase(content), Strings.UCase("Invalid Username Or Password")) > 0)
                                {
                                    strresponse = "Sending Failed. Invalid Username Or Password.";
                                }
                                else
                                {
                                    strresponse = "Message Send Successfully.";
                                }
                            }
                            else if (Strings.InStr(1, Strings.UCase(content), "FAIL") > 0)
                            {
                                strresponse = "Message Sending Failed";
                            }
                            else if (Strings.InStr(1, Strings.UCase(content), "INVALID USERNAME OR PASSWORD") > 0 | Strings.InStr(1, Strings.UCase(content), "INVALID USERNAME AND PASSWORD") > 0)
                            {
                                strresponse = "Message Sending Failed. Invalid Username Or Password.";
                            }
                            else if (Strings.InStr(1, Strings.UCase(content), "1701|") > 0 | Strings.InStr(1, Strings.UCase(content), "SUCCESS") > 0)
                            {
                                strresponse = "Message Send Successfully.";
                            }
                            else if (Strings.InStr(1, Strings.UCase(content), ":") > 0)
                            {
                                if (string.IsNullOrEmpty(Strings.Split(Strings.UCase(content), ":")[1]))
                                {
                                    strresponse = content;
                                }
                                else
                                {
                                    strresponse = "Message Send Successfully.";
                                }
                            }
                            else if (content == "100")
                            {
                                strresponse = "Message Send Successfully.";
                            }
                            else if (Strings.InStr(1, Strings.UCase(content), "GID") > 0)
                            {
                                strresponse = "Message Send Successfully.";
                            }
                            else
                            {
                                strresponse = content;
                            }
                        }
                        catch (Exception ex)
                        {
                        }

                        if (Convert.ToInt16(fnFireQuery("SysObjects", "count(*)", "name", "SMS_Logs", true)) == 0)
                        {
                            strsql = "";
                            strsql += " CREATE TABLE [dbo].[SMS_Logs]( ";
                            strsql += " [sl_CmCd] [char](16) NOT NULL, ";
                            strsql += " [sl_Mobile] [char](15) NOT NULL, ";
                            strsql += " [sl_Message] [varchar](2000) NOT NULL, ";
                            strsql += " [sl_Response] [char](150) NOT NULL, ";
                            strsql += " [mkrid] [char](8) NOT NULL, ";
                            strsql += " [mkrdt] [char](8) NOT NULL, ";
                            strsql += " [mkrtm] [char](8) NOT NULL )";
                            ExecuteSQL(strsql);
                        }

                        strsql = "Insert into sms_Logs values(";
                        strsql += "'" + clientCd.ToUpper() + "','" + strMobileNo + "','" + strMsgTxt + "',";
                        strsql += "'" + strresponse.Replace("'", " ") + "','" + Strings.Right(clientCd.ToUpper(), 8) + "',Convert(char,getdate(),112),Convert(char,getdate(),108))";
                        ExecuteSQL(strsql);

                        /*strsql = "Update OTP_Master set OTP_Status = 'E' where OTP_ClientCode='" + clientCd.ToUpper() + "' and OTP_Product = '" + Product + "' and OTP_Type = '" + Mode + "' and OTP_Status = 'P'";
                        ExecuteSQL(strsql);

                        strsql = "Insert into OTP_Master values('" + clientCd.ToUpper() + "', 'MO', '" + strSotp.Trim() + "','" + strMobileNo + "', CONVERT(CHAR(8),GETDATE(),112), CONVERT(VARCHAR(8), GETDATE(), 108), CONVERT(CHAR(8), DATEADD(MINUTE, " + intOTPValidTime + ", GETDATE()), 112),CONVERT(VARCHAR(8), DATEADD(MINUTE, " + intOTPValidTime + ", GETDATE()), 108),'P','" + Product + "', '" + Mode + "','','','',0,0,0)";
                        ExecuteSQL(strsql);*/

                        blnOTP = true;

                        dtTable.Rows.Add("Y", "OTP sent to your registered mobile " + strMobile);
                        //return dtTable;
                    }
                    else
                    {
                        dtTable.Rows.Add("N", "Client Not Found");
                        return dtTable;
                    }

                    if (Convert.ToInt32(fnFireQueryTradeWeb("WebParameter", "count(0)", "sp_parmcd", "SMTPSERVERW", true)) > 0)
                    {
                        try
                        {
                            string strHost = string.Empty;
                            int intPort;
                            string strEmailUserID = string.Empty;
                            string strPWD = string.Empty;
                            string strEmailCC = string.Empty;
                            string strSSL = string.Empty;
                            string strUserCd = string.Empty;
                            string strToEmailId = string.Empty;
                            string strEmailResp = string.Empty;
                            string strEmailErr = string.Empty;
                            string strSMTPParamVal = fnFireQueryTradeWeb("WebParameter", "SP_SYSVALUE", "sp_parmcd", "SMTPSERVERW", true);
                            string[] emmailValues = strSMTPParamVal.Split('/');
                            if (emmailValues.Length > 5)
                            {
                                try
                                {
                                    strHost = strSMTPParamVal.Split('/')[0];
                                    intPort = Convert.ToInt32(strSMTPParamVal.Split('/')[1]);
                                    strEmailUserID = strSMTPParamVal.Split('/')[2];
                                    strPWD = strSMTPParamVal.Split('/')[3];
                                    strEmailCC = strSMTPParamVal.Split('/')[4];
                                    strSSL = strSMTPParamVal.Split('/')[5];

                                    DataSet ds = new DataSet();
                                    strsql = "Select * from Client_master where cm_cd = '" + clientCd + "'";
                                    ds = OpenDataSet(strsql);
                                    if (ds.Tables[0].Rows.Count == 0)
                                    {
                                        dtTable.Rows.Add("N", "Client Not Found");
                                        return dtTable;
                                    }
                                    if (ds.Tables[0].Rows[0]["cm_email"].ToString().Trim() == "")
                                    {
                                        dtTable.Rows.Add("N", "EmailID is not available");
                                        return dtTable;
                                    }
                                    strToEmailId = ds.Tables[0].Rows[0]["cm_email"].ToString().Trim();

                                    StringBuilder sb = new StringBuilder(strToEmailId);
                                    for (int i = 2; i <= strToEmailId.Length - 3; i++)
                                    {
                                        sb[i] = 'x';
                                    }
                                    string strEmailRtn = sb.ToString();

                                    MailMessage Msg = new MailMessage();
                                    Msg.From = new MailAddress(strEmailUserID);
                                    Msg.To.Add(strToEmailId);
                                    if (!string.IsNullOrEmpty(strEmailCC))
                                        Msg.CC.Add(strEmailCC);
                                    Msg.Subject = "Your OTP to access TradeWeb";
                                    Msg.Body = strMsgTxt;
                                    Msg.IsBodyHtml = true;
                                    SmtpClient smtp = new SmtpClient();
                                    smtp.Host = strHost;
                                    smtp.Port = intPort;
                                    smtp.UseDefaultCredentials = false;
                                    smtp.Credentials = new System.Net.NetworkCredential(strEmailUserID, strPWD);
                                    smtp.EnableSsl = strSSL == "N" ? false : true;
                                    System.Net.ServicePointManager.ServerCertificateValidationCallback = delegate (object s,
                                    System.Security.Cryptography.X509Certificates.X509Certificate certificate,
                                    System.Security.Cryptography.X509Certificates.X509Chain chain,
