                                    if (dtTable.Rows.Count > 0)
                                    {
                                        if (dtTable.Rows[0]["Status"].ToString().Trim() == "Y")
                                        {
                                            dtTable.Rows[0]["Message"] += " OTP sent to your registered email " + strEmailRtn;
                                        }
                                    }
                                    else
                                    {
                                        dtTable.Rows.Add("Y", "OTP sent to your registered email " + strEmailRtn);
                                    }

                                    /*if (!blnOTP)
                                    {
                                        strsql = "Update OTP_Master set OTP_Status = 'E' where OTP_ClientCode='" + clientCd.ToUpper() + "' and OTP_Product = '" + Product + "' and OTP_Type = '" + Mode + "' and OTP_Status = 'P'";
                                        ExecuteSQL(strsql);

                                        strsql = "Insert into OTP_Master values('" + clientCd.ToUpper() + "', 'EI', '" + strSotp.Trim() + "','" + strToEmailId + "', CONVERT(CHAR(8),GETDATE(),112), CONVERT(VARCHAR(8), GETDATE(), 108), CONVERT(CHAR(8), DATEADD(MINUTE, " + intOTPValidTime + ", GETDATE()), 112),CONVERT(VARCHAR(8), DATEADD(MINUTE, " + intOTPValidTime + ", GETDATE()), 108),'P','" + Product + "', '" + Mode + "','','','',0,0,0)";
                                        ExecuteSQL(strsql);
                                    }*/
                                }
                                catch (Exception e)
                                {
                                    if (!blnOTP)
                                    {
                                        dtTable.Rows.Add("N", "Error Sending Email.");
                                    }
                                    else
                                    {
                                        dtTable.Rows[0]["Message"] += " Error Sending Email.";
                                    }
                                    return dtTable;
                                }
                            }
                        }
                        catch (Exception)
                        {
                            if (!blnOTP)
                            {
                                dtTable.Rows.Add("N", "Error Sending Email.");
                            }
                            else
                            {
                                dtTable.Rows[0]["Message"] += " Error Sending Email.";
                            }
                            return dtTable;
                        }
                    }
                }
                return dtTable;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public void CreateOTPMasterTable()
        {
            using (SqlConnection objConnection = new SqlConnection(GetConnectionStr()))
            {
                objConnection.Open();

                try
                {
                    string Strsql = "";
                    if (!fnchkTable("OTP_Master"))
                    {
                        Strsql = "CREATE TABLE OTP_Master(";
                        Strsql += " [OTP_Identity] [int] IDENTITY(1,1) NOT NULL,";
                        Strsql += " [OTP_ClientCode] [char](8) NOT NULL,";
                        Strsql += " [OTP_Item] [char](2) NOT NULL,";
                        Strsql += " [OTP_OTP] [varchar](8) NOT NULL,";
                        Strsql += " [OTP_SentTo] [varchar](50) NOT NULL,";
                        Strsql += " [OTP_SentDate] [char](8) NOT NULL,";
                        Strsql += " [OTP_SentTime] [char](8) NOT NULL,";
                        Strsql += " [OTP_ValidTillDate] [char](8) NOT NULL,";
                        Strsql += " [OTP_ValidTillTime] [char](8) NOT NULL,";
                        Strsql += " [OTP_Status] [char](1) NOT NULL,";
                        Strsql += " [OTP_Product] [varchar](50) NOT NULL,";
                        Strsql += " [OTP_Type] [varchar](10) NOT NULL,";
                        Strsql += " [OTP_Filler1] [char](1) NOT NULL,";
                        Strsql += " [OTP_Filler2] [char](1) NOT NULL,";
                        Strsql += " [OTP_Filler3] [char](1) NOT NULL,";
                        Strsql += " [OTP_NFiller1] [numeric](18, 0) NOT NULL,";
                        Strsql += " [OTP_NFiller2] [numeric](18, 0) NOT NULL,";
                        Strsql += " [OTP_NFiller3] [numeric](18, 0) NOT NULL,";
                        Strsql += " CONSTRAINT [PK_OTPMaster] PRIMARY KEY CLUSTERED ([OTP_Identity]))";
                        ExecuteSQL(Strsql);
                    }

                    if (Convert.ToInt32(fnFireQueryTradeWeb("Information_Schema.Columns", "count(*)", "Table_Name='OTP_Master' and Column_Name", "OTP_Product", true)) == 0)
