                            Strsql = "Alter Table OTP_Master Add OTP_Product VARCHAR(50)";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Update OTP_Master Set OTP_Product='' where OTP_Product IS NULL";
