                            Strsql = "Alter Table OTP_Master Alter Column OTP_Product VARCHAR(50) NOT NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);

                            Strsql = "Alter Table OTP_Master Add OTP_Type VARCHAR(10)";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Update OTP_Master Set OTP_Type='' where OTP_Type IS NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Alter Table OTP_Master Alter Column OTP_Type VARCHAR(10) NOT NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);

                            Strsql = "Alter Table OTP_Master Add OTP_Filler1 CHAR(1)";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Update OTP_Master Set OTP_Filler1='' where OTP_Filler1 IS NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Alter Table OTP_Master Alter Column OTP_Filler1 CHAR(1) NOT NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);

                            Strsql = "Alter Table OTP_Master Add OTP_Filler2 CHAR(1)";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Update OTP_Master Set OTP_Filler2='' where OTP_Filler2 IS NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Alter Table OTP_Master Alter Column OTP_Filler2 CHAR(1) NOT NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);

                            Strsql = "Alter Table OTP_Master Add OTP_Filler3 CHAR(1)";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Update OTP_Master Set OTP_Filler3='' where OTP_Filler3 IS NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Alter Table OTP_Master Alter Column OTP_Filler3 CHAR(1) NOT NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);

                            Strsql = "Alter Table OTP_Master Add OTP_NFiller1 numeric";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Update OTP_Master Set OTP_NFiller1=0 where OTP_NFiller1 IS NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Alter Table OTP_Master Alter Column OTP_NFiller1 numeric NOT NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);

                            Strsql = "Alter Table OTP_Master Add OTP_NFiller2 numeric";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Update OTP_Master Set OTP_NFiller2=0 where OTP_NFiller2 IS NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Alter Table OTP_Master Alter Column OTP_NFiller2 numeric NOT NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);

                            Strsql = "Alter Table OTP_Master Add OTP_NFiller3 numeric";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Update OTP_Master Set OTP_NFiller3=0 where OTP_NFiller3 IS NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);
                            Strsql = "Alter Table OTP_Master Alter Column OTP_NFiller3 numeric NOT NULL";
                            ExecuteSQL(Strsql, objConnection, objTrans);

                            objTrans.Commit();
                        }
                        catch (Exception ex)
                        {
                            objTrans.Rollback();
                            throw ex;
                        }
                    }
                }
                catch (Exception ex)
                {
                    throw ex;
                }
            }
        }

        public DateTime GetSqlCurrentDateTime()
        {
            DateTime currentDateTime;

            string query = "SELECT GETDATE()";

            using (SqlConnection conn = new SqlConnection(GetConnectionStr()))
            {
                using SqlCommand cmd = new SqlCommand(query, conn);
                conn.Open();
                currentDateTime = (DateTime)cmd.ExecuteScalar();
            }

            return currentDateTime;
        }


        public string SerializeToXml<T>(T obj, bool omitXmlDeclaration = false, bool indent = false, string encoding = "utf-8")
        {
            if (obj == null)
            {
                throw new ArgumentNullException(nameof(obj));
            }
            var xmlSerializer = new XmlSerializer(typeof(T));

            var xmlWriterSettings = new XmlWriterSettings
            {
                OmitXmlDeclaration = omitXmlDeclaration,
                Indent = indent,
                Encoding = Encoding.GetEncoding(encoding)
            };
            using (var stringWriter = new StringWriterWithEncoding(Encoding.GetEncoding(encoding)))
            {
                using (var xmlWriter = XmlWriter.Create(stringWriter, xmlWriterSettings))
                {
                    xmlSerializer.Serialize(xmlWriter, obj);
                    return stringWriter.ToString();
                }
            }
        }

        private class StringWriterWithEncoding : StringWriter
        {
            private readonly Encoding encoding;

            public StringWriterWithEncoding(Encoding encoding)
            {
                this.encoding = encoding;
            }
            public override Encoding Encoding => encoding;
        }


        public string CheckPasswordCondition(string newPassword, string dpid, string clientCode)
        {
            try
            {
                double intLastPass = Conversion.Val(GetWebParameter("PWDSAMECHK"));
                string Strsql = "";
                if (intLastPass > 0)
                {
                    if (!fnchkTable("Password_history"))
                    {
                        Strsql = "CREATE TABLE Password_history(";
                        Strsql += "[ph_srno] [numeric](18, 0) IDENTITY(1,1) NOT NULL,";
                        Strsql += "[ph_dpid] [char](8) NOT NULL,";
                        Strsql += "[ph_code] [char](8) NOT NULL,";
                        Strsql += "[ph_logintype] [char](1) NOT NULL,";
                        Strsql += "[ph_password] [char](10) NOT NULL,";
                        Strsql += "[mkrdt] [char](8) NOT NULL";
                        Strsql += ")";
                        ExecuteSQL(Strsql);
                    }
                }

                if (ConfigurationManager["IsTradeWeb"] == "C" || ConfigurationManager["IsTradeWeb"] == "E")
                {
                    string strPwdSetting = fnFireQueryTradeWeb("webparameter", "sp_sysvalue", "sp_parmcd", "PWDSETTING", true);
                    if (strPwdSetting != "")
                    {
                        string strPwdMinLen = strPwdSetting.Split('/')[0];
                        string strPwdFormat = strPwdSetting.Split('/')[1];
                        if (newPassword.Length < Convert.ToInt32(strPwdMinLen))
                        {
                            return "Password should contain minimum " + strPwdMinLen + " characters.";
                        }
                        if (strPwdFormat.Trim() == "Y")
                        {
                            int intPwdAlphaCnt = 0;
                            int intPwdNumCnt = 0;
                            int intPwdSplCnt = 0;
                            string strNewPwd = newPassword;
                            for (int i = 0; i <= strNewPwd.Length - 1; i++)
                            {
                                if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 65 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 90)
                                {
                                    intPwdAlphaCnt++;
                                }
                                else if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 97 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 122)
                                {
                                    intPwdAlphaCnt++;
                                }
                                else if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 48 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 57)
                                {
                                    intPwdNumCnt++;
                                }
                                else
                                {
                                    intPwdSplCnt++;
                                }
                            }
                            if (intPwdNumCnt == 0)
                            {
                                return "Password should contain at least one number.";
                            }
                            if (intPwdAlphaCnt == 0)
                            {
                                return "Password should contain at least one Alphabet.";
                            }
                            if (intPwdSplCnt == 0)
                            {
                                return "Password should contain at least one special character.";
                            }
                        }
                    }
                }

                if (ConfigurationManager["IsTradeWeb"] == "O")
                {
                    double intMinChar = Conversion.Val(GetSysParmSt("PWDMINCHR", ""));
                    string strAlphaNum = GetSysParmSt("PWDALPHANUM", "");

                    if (intMinChar > 0)
                    {
                        if (newPassword.Length < intMinChar)
                        {
                            return "Password should contain minimum " + intMinChar + " characters.";
                        }
                    }
                    if (strAlphaNum.Trim() == "Y")
                    {
                        int intPwdAlphaCnt = 0;
                        int intPwdNumCnt = 0;
                        int intPwdSplCnt = 0;

                        for (int i = 0; i <= newPassword.Length - 1; i++)
                        {
                            if (Strings.Asc(newPassword.Substring(i, 1)) >= 65 && Strings.Asc(newPassword.Substring(i, 1)) <= 90)
                            {
                                intPwdAlphaCnt++;
                            }
                            else if (Strings.Asc(newPassword.Substring(i, 1)) >= 97 && Strings.Asc(newPassword.Substring(i, 1)) <= 122)
                            {
                                intPwdAlphaCnt++;
                            }
                            else if (Strings.Asc(newPassword.Substring(i, 1)) >= 48 && Strings.Asc(newPassword.Substring(i, 1)) <= 57)
                            {
                                intPwdNumCnt++;
                            }
                            else
                            {
                                intPwdSplCnt++;
                            }
                        }
                        if (intPwdNumCnt == 0)
                        {
                            return "Password should contain at least one number.";
                        }
                        if (intPwdAlphaCnt == 0)
                        {
                            return "Password should contain at least one Alphabet.";
                        }
                        if (intPwdSplCnt == 0)
                        {
                            return "Password should contain at least one special character.";
                        }
                    }
                }

                /*if (intLastPass > 0)
                {
                    if (CheckPreviousPassword(intLastPass, dpid, clientCode, newPassword))
                    {
                        return "You cannot use any of the previous " + intLastPass + " passwords. Please set a different password.!";
                    }
                }*/

                int pwdMaxLenght = Convert.ToInt32(ExecuteSQLReturn("SELECT character_maximum_length as 'Max Length'  FROM information_schema.columns  WHERE table_name = 'Client_Master' and COLUMN_NAME='CM_PWD'"));
                if (newPassword.Length > pwdMaxLenght)
                {
                    return "Password maximum length should be " + pwdMaxLenght + " characters.";
                }
            }
            catch (Exception ex) { }

            return "";
        }

        public bool CheckPreviousPassword(double intLastPass, string strDPID, string strCode, string strNewPassword)
        {
            bool blnPwd = false;

            if (GetWebParameter("TWEBENCPWD") == "Y")
            {
                strNewPassword = Encrypt(strNewPassword);
            }

            string Strsql = "select top " + intLastPass + " ph_dpid, ph_code, ph_password from Password_history where ph_logintype='C' and ph_dpid = '" + strDPID + "' and ph_code='" + strCode + "' order by ph_srno desc";
            DataTable dtPass = OpenDataTable(Strsql);
            foreach (DataRow dr in dtPass.Rows)
            {
                if (dr["ph_password"].ToString().Trim() == strNewPassword)
                {
                    blnPwd = true;
                    break;
                }
            }
            return blnPwd;
        }

