        public string VerifyOtp_OtpMaster(string userId, string strOTP, string mobile_Email, string modeType, string product)
        {
            try
            {
                ////// Check otp
                string checkOTP = "", strIdentity = "", strMobileNo = "", OTP = strOTP;
                int maxOtpFailCount = 0;
                string Strsql = "select top 1 OTP_Identity,OTP_OTP,OTP_ValidTillDate,OTP_ValidTillTime, OTP_SentTo, OTP_NFiller1  from OTP_Master with (NoLock) where OTP_ClientCode='" + userId + "' and OTP_Status='P' and OTP_Product='" + product + "' and OTP_Type = '" + modeType + "' and OTP_SentTo = '" + mobile_Email + "' order by OTP_Identity desc";
                DataTable dtOtp = OpenDataTable(Strsql);
                if (dtOtp.Rows.Count > 0)
                {
                    checkOTP = dtOtp.Rows[0]["OTP_OTP"].ToString().Trim();
                    strIdentity = dtOtp.Rows[0]["OTP_Identity"].ToString().Trim();
                    strMobileNo = dtOtp.Rows[0]["OTP_SentTo"].ToString().Trim();
                    maxOtpFailCount = Convert.ToInt32(dtOtp.Rows[0]["OTP_NFiller1"].ToString());
                }
                if (maxOtpFailCount >= 3)
                {
                    return "Maximum OTP attempts reached. Please generate a new OTP.";
                }
                else if (!string.IsNullOrWhiteSpace(OTP) && !string.IsNullOrWhiteSpace(checkOTP) && OTP == checkOTP)
                {
                    DateTime dtNow = GetSqlCurrentDateTime();
                    DateTime dt3 = stod(dtOtp.Rows[0]["OTP_ValidTillDate"].ToString());
                    TimeSpan time = TimeSpan.Parse(dtOtp.Rows[0]["OTP_ValidTillTime"].ToString());
                    DateTime dtExpiry = dt3 + time;
                    if (dtNow > dtExpiry)
                    {
                        Strsql = "update OTP_Master set OTP_Status='E' where OTP_Identity='" + strIdentity + "'";
                        ExecuteSQL(Strsql);
                        return "OTP has been expired";
                    }
                    Strsql = "update OTP_Master set OTP_Status='M' where OTP_Identity='" + strIdentity + "'";
                    ExecuteSQL(Strsql);
                }
                else
                {
                    Strsql = "update OTP_Master set OTP_NFiller1=" + (maxOtpFailCount + 1) + " where OTP_Identity='" + strIdentity + "'";
                    ExecuteSQL(Strsql);
                    return "OTP Mismatched";
                }
            }
            catch (Exception e)
            {
            }
            return "success";
        }

        public bool VerifySignature(string payload, string publicKeyBase64, string signatureBase64)
        {
            byte[] publicKeyBytes = Convert.FromBase64String(publicKeyBase64);
            byte[] payloadBytes = Encoding.UTF8.GetBytes(payload);
            byte[] signatureBytes = Convert.FromBase64String(signatureBase64);

            using (RSA rsa = RSA.Create())
            {
                rsa.ImportSubjectPublicKeyInfo(publicKeyBytes, out _); // Import PKCS#8 public key

                return rsa.VerifyData(payloadBytes, signatureBytes, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
            }
        }

        public CommonXMLResponse CreateCommonXML(XmlDocument xml, string role, string userId)
        {
            // Extract and parse J_Ui element
            var jUiObject = ParseJsonFromXml<JUiModel>(xml, "J_Ui", out string jUiError);
            if (jUiObject == null)
            {
                return new CommonXMLResponse { Success = false, Message = jUiError, ModuleName = "", FunctionName = "" };
            }

            // Extract and parse J_Api element (if exists)
            var jApiObject = ParseJsonFromXml<JApi>(xml, "J_Api", out string jApiError);
            if (jApiError != null)
            {
                return new CommonXMLResponse { Success = false, Message = jApiError, ModuleName = "", FunctionName = "" };
            }

            if (jApiObject != null)
            {
                if (role != "ComAPI")
                {
                    jApiObject.UserId = userId.Trim();
                }
                UpdateXmlNodeWithJson(xml, "J_Api", jApiObject);
            }

            // Handle X_Filter (prevent null exception)
            var filterXml = xml.GetElementsByTagName("X_Filter")[0]?.InnerXml;
            if (!string.IsNullOrWhiteSpace(filterXml))
            {
                XDocument xdoc = XDocument.Parse($"<root>{filterXml}</root>");
                xml.DocumentElement["X_Filter"].InnerXml = xdoc.Root.ToString(SaveOptions.DisableFormatting)
                    .Replace("<root>", "").Replace("</root>", "");
            }

            return new CommonXMLResponse
            {
                Success = true,
                Message = "",
                ModuleName = jUiObject.ActionName.Trim() ?? "",
                FunctionName = jUiObject.Option.Trim() ?? "",
                ReportDisplay = jUiObject.ReportDisplay.Trim() ?? ""
            };
        }

        private T ParseJsonFromXml<T>(XmlDocument xml, string tagName, out string errorMessage) where T : class
        {
            errorMessage = null;
            string jsonString = xml.GetElementsByTagName(tagName)[0]?.InnerText;

            if (string.IsNullOrWhiteSpace(jsonString))
            {
                errorMessage = $"{tagName} element is empty or missing.";
                return null;
            }

            jsonString = "{" + jsonString.Replace("\u201C", "\"").Replace("\u201D", "\"") + "}";

            try
            {
                return JsonConvert.DeserializeObject<T>(jsonString);
            }
            catch (JsonException ex)
            {
                errorMessage = $"Invalid JSON in {tagName} element: {ex.Message}";
                return null;
            }
        }

        private void UpdateXmlNodeWithJson(XmlDocument xml, string tagName, object jsonObject)
        {
            XmlNode node = xml.DocumentElement[tagName];
            if (node != null)
            {
                string jsonString = JsonConvert.SerializeObject(jsonObject)
                    .Replace("{", "").Replace("}", ""); // Remove enclosing braces
                node.InnerText = jsonString;
            }
        }

        public string EDIS_Encrypt(string plainText, string KeyString)
        {
            byte[] key = ASCIIEncoding.UTF8.GetBytes(KeyString);
            byte[] iv = new byte[16] { 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0 };
            // Instantiate a new Aes object to perform string symmetric encryption
            Aes encryptor = Aes.Create();

            encryptor.Mode = CipherMode.CBC;
            //encryptor.KeySize = 256;
            //encryptor.BlockSize = 128;
            //encryptor.Padding = PaddingMode.Zeros;

            // Set key and IV
            encryptor.Key = key.Take(32).ToArray();
            encryptor.IV = iv;

            // Instantiate a new MemoryStream object to contain the encrypted bytes
            MemoryStream memoryStream = new MemoryStream();

            // Instantiate a new encryptor from our Aes object
            ICryptoTransform aesEncryptor = encryptor.CreateEncryptor();

            // Instantiate a new CryptoStream object to process the data and write it to the 
            // memory stream
            CryptoStream cryptoStream = new CryptoStream(memoryStream, aesEncryptor, CryptoStreamMode.Write);

            // Convert the plainText string into a byte array
            byte[] plainBytes = Encoding.ASCII.GetBytes(plainText);

            // Encrypt the input plaintext string
            cryptoStream.Write(plainBytes, 0, plainBytes.Length);

            // Complete the encryption process
            cryptoStream.FlushFinalBlock();

            // Convert the encrypted data from a MemoryStream to a byte array
            byte[] cipherBytes = memoryStream.ToArray();

            // Close both the MemoryStream and the CryptoStream
            memoryStream.Close();
            cryptoStream.Close();

            // Convert the encrypted byte array to a base64 encoded string
            string cipherText = Convert.ToBase64String(cipherBytes, 0, cipherBytes.Length);

            // Return the encrypted data as a string
            return cipherText;
        }

        public string EDIS_Decrypt(string cipherText, string KeyString)
        {
            try
            {
                byte[] key = ASCIIEncoding.UTF8.GetBytes(KeyString);
                byte[] iv = new byte[16] { 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0 };

                // Instantiate a new Aes object to perform string symmetric encryption
                Aes decryptor = Aes.Create();

                decryptor.Mode = CipherMode.CBC;
                decryptor.Key = key.Take(32).ToArray();
                decryptor.IV = iv;

                // Instantiate a new MemoryStream object to contain the decrypted bytes
                MemoryStream memoryStream = new MemoryStream();

                // Instantiate a new decryptor from our Aes object
                ICryptoTransform aesDecryptor = decryptor.CreateDecryptor();

                // Instantiate a new CryptoStream object to process the data and write it to the memory stream
                CryptoStream cryptoStream = new CryptoStream(memoryStream, aesDecryptor, CryptoStreamMode.Write);

                // Convert the base64-encoded string to a byte array
                byte[] cipherBytes = Convert.FromBase64String(cipherText);

                // Decrypt the input ciphertext bytes
                cryptoStream.Write(cipherBytes, 0, cipherBytes.Length);

                // Complete the decryption process
                cryptoStream.FlushFinalBlock();

                // Convert the decrypted data from a MemoryStream to a byte array
                byte[] plainBytes = memoryStream.ToArray();

                // Close both the MemoryStream and the CryptoStream
                memoryStream.Close();
                cryptoStream.Close();

                // Convert the decrypted byte array to a string using ASCII encoding
                string plainText = Encoding.ASCII.GetString(plainBytes);

                // Return the decrypted data as a string
                return plainText;
            }
            catch (Exception ex)
            {
                // Handle decryption errors, e.g., incorrect key or corrupted data
                Console.WriteLine("Decryption error: " + ex.Message);
                return null;
            }
        }

        public VersionInfo GetVersionInfo(VersionData versionData, SqlConnection sqlcon = null)
        {
            try
            {
                string strFormat = "yyyyMMddHHmmss";
                var culture = System.Globalization.CultureInfo.InvariantCulture;
                var style = System.Globalization.DateTimeStyles.None;

                string strPath = Path.Combine(Directory.GetCurrentDirectory(), "SQL", versionData.ApplicationName + ".sql");
                DateTime LastWriteTime = File.GetLastWriteTime(strPath);
                LastWriteTime = new DateTime(LastWriteTime.Year, LastWriteTime.Month, LastWriteTime.Day, LastWriteTime.Hour, LastWriteTime.Minute, LastWriteTime.Second);

                string strLocalSPFileDate = LastWriteTime.ToString("yyyyMMddHHmmss");
                string strParamSPDate = "";
                string strParamQueryDate = "";
                if (sqlcon == null)
                {
                    strParamSPDate = GetWebParameter(versionData.ApplicationName + "SPDT");
                    strParamQueryDate = GetWebParameter(versionData.ApplicationName + "DBDT");
                }
                else
                {
                    strParamSPDate = GetWebParameter(versionData.ApplicationName + "SPDT", sqlcon);
                    strParamQueryDate = GetWebParameter(versionData.ApplicationName + "DBDT", sqlcon);
                }
                string strWebSPDate = versionData.SPDate;
                string strWebSPStatus = "";
                string strWebQueryDate = versionData.DBDate;

                ParseVersion(strWebSPDate, out strWebSPDate, out strWebSPStatus);

                DateTime LocalSPFileDate, ParamSPDate, ParamQueryDate, WebSPDate, WebQueryDate;

                bool isLocalSPDateValid = DateTime.TryParseExact(strLocalSPFileDate, strFormat, culture, style, out LocalSPFileDate);
                bool isParamDateValid = DateTime.TryParseExact(strParamSPDate, strFormat, culture, style, out ParamSPDate);
                bool isQueryDateValid = DateTime.TryParseExact(strParamQueryDate, strFormat, culture, style, out ParamQueryDate);
                bool isWebDBDateValid = DateTime.TryParseExact(strWebSPDate, strFormat, culture, style, out WebSPDate);
                bool isWebQueryDateValid = DateTime.TryParseExact(strWebQueryDate, strFormat, culture, style, out WebQueryDate);

                return new VersionInfo
                {
                    LocalSPFileDate = LocalSPFileDate,
                    ParamSPFileDate = ParamSPDate,
                    WebSPFileDate = WebSPDate,
                    WebSPFileStatus = strWebSPStatus,
                    ParamDBDate = ParamQueryDate,
                    WebDBDate = WebQueryDate
                };
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public void ParseVersion(string versionInput, out string version, out string status)
        {
            if (!string.IsNullOrEmpty(versionInput) && versionInput.Contains("~"))
            {
                string[] parts = versionInput.Split('~');
                version = parts[0];
                status = parts.Length > 1 ? parts[1] : "O";
            }
            else
            {
                version = versionInput;
                status = "O";
            }
        }

        public void CheckSPNew(string strParamCode, SqlConnection conn = null)
        {
            try
            {
                string strsql = "";
                string strPath = Path.Combine(Directory.GetCurrentDirectory(), "SQL", strParamCode + ".sql");

                if (!File.Exists(strPath))
                {
                    return;
                }

                DateTime LastWriteTime = File.GetLastWriteTime(strPath);
                //removing milliseconds for comparision
                LastWriteTime = new DateTime(LastWriteTime.Year, LastWriteTime.Month, LastWriteTime.Day, LastWriteTime.Hour, LastWriteTime.Minute, LastWriteTime.Second);

                var db = new DataContext();
                SqlConnection sqlCon = conn ?? new SqlConnection(db.Database.GetDbConnection().ConnectionString);
                bool blnShouldClose = false;

                if (conn == null)
                {
                    blnShouldClose = true;
                }
                if (sqlCon.State == ConnectionState.Closed)
                {
                    sqlCon.Open();
                }

                // Read the content of the .sql file
                string sqlScript = "";

                using (StreamReader reader = new StreamReader(strPath, Encoding.UTF8))
                {
                    string strFileText = reader.ReadToEnd();
                    //string strEnc = Convert.ToBase64String(EncryptStringToBytes_Aes(strFileText, Encoding.UTF8.GetBytes("5F4E3D2C1B0A9876"), Encoding.UTF8.GetBytes("7A6B5C4D3E2F1A09")));
                    sqlScript = DecryptStringFromBytes_Aes(Convert.FromBase64String(strFileText), Encoding.UTF8.GetBytes("5F4E3D2C1B0A9876"), Encoding.UTF8.GetBytes("7A6B5C4D3E2F1A09"));
                }
                string[] batches = Regex.Split(sqlScript, @"^\s*GO\s*$", RegexOptions.Multiline);

                foreach (string batch in batches)
                {
                    if (batch.Trim() != "")
                    {
                        try
                        {
                            using SqlCommand command = new SqlCommand(batch, sqlCon);
                            command.ExecuteNonQuery();
                        }
                        catch (SqlException ex)
                        {
                            throw ex;
                        }
                    }
                }

                if (Convert.ToInt16(fnFireQueryTradeWeb("webparameter", "count(0)", "sp_parmcd", strParamCode + "SPDT", true, sqlCon)) > 0)
                {
                    strsql = "update webparameter set sp_sysvalue = '" + LastWriteTime.ToString("yyyyMMddHHmmss") + "' where sp_parmcd='" + strParamCode + "SPDT'";
                }
                else
                {
                    strsql = "Insert into Webparameter values('" + strParamCode + "SPDT', '" + strParamCode + " SP Date', '" + LastWriteTime.ToString("yyyyMMddHHmmss") + "')";
                }
                ExecuteSQL(strsql, sqlCon);

                if (blnShouldClose)
                {
                    sqlCon.Dispose();
                }
                return;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public (string Status, string Message) InsertOTP(string clientCd, string strSotp, string strMobileNo, string strItem, string Product, string Mode, int intOTPValidTime, SqlConnection objConnection)
        {
            try
            {
                int intAttempts = 10;
                int intMinutes = 15;
                string strParmOTP = GetWebParameter("OTPMAXATMPT");
                if (!string.IsNullOrWhiteSpace(strParmOTP) && strParmOTP.Contains("~"))
                {
                    var parts = strParmOTP.Split('~');
                    if (parts.Length == 2)
                    {
                        int.TryParse(parts[0], out intAttempts);
                        int.TryParse(parts[1], out intMinutes);
                    }
                }

                string strsql = @"
                BEGIN TRANSACTION;

                IF (
                    SELECT COUNT(1)
                    FROM OTP_Master WITH (UPDLOCK, HOLDLOCK)
                    WHERE OTP_ClientCode = @ClientCode
                      AND OTP_Product = @Product
                      AND OTP_Type = @Mode
                      AND CAST(OTP_SentDate AS DATETIME) + CAST(OTP_SentTime AS DATETIME)
                          >= DATEADD(MINUTE, -@LimitMinutes, GETDATE())
                ) < @MaxAttempts
                BEGIN
                    UPDATE OTP_Master
                    SET OTP_Status = 'E'
                    WHERE OTP_ClientCode = @ClientCode
                      AND OTP_Product = @Product
                      AND OTP_Type = @Mode
                      AND OTP_Status = 'P';

                    INSERT INTO OTP_Master (
                        OTP_ClientCode, OTP_Item, OTP_OTP, OTP_SentTo,
                        OTP_SentDate, OTP_SentTime, OTP_ValidTillDate, OTP_ValidTillTime,
                        OTP_Status, OTP_Product, OTP_Type,
                        OTP_Filler1, OTP_Filler2, OTP_Filler3,
                        OTP_NFiller1, OTP_NFiller2, OTP_NFiller3
                    )
                    VALUES (
                        @ClientCode, @Item, @OtpValue, @MobileNo,
                        CONVERT(CHAR(8), GETDATE(), 112), CONVERT(VARCHAR(8), GETDATE(), 108),
                        CONVERT(CHAR(8), DATEADD(MINUTE, @ValidMinutes, GETDATE()), 112),
                        CONVERT(VARCHAR(8), DATEADD(MINUTE, @ValidMinutes, GETDATE()), 108),
                        'P', @Product, @Mode,
                        '', '', '', 0, 0, 0
                    );

                    COMMIT TRANSACTION;
                    SELECT 1; --Success
                END
                ELSE
                BEGIN
                    ROLLBACK TRANSACTION;
                    SELECT 0; --Too many attempts
                END";

                SqlCommand cmd1 = new SqlCommand(strsql, objConnection);
                cmd1.Parameters.AddWithValue("@ClientCode", clientCd.ToUpper());
                cmd1.Parameters.AddWithValue("@OtpValue", strSotp.Trim());
                cmd1.Parameters.AddWithValue("@MobileNo", strMobileNo);
                cmd1.Parameters.AddWithValue("@Item", strItem);
                cmd1.Parameters.AddWithValue("@Product", Product);
                cmd1.Parameters.AddWithValue("@Mode", Mode);
                cmd1.Parameters.AddWithValue("@ValidMinutes", intOTPValidTime);
                cmd1.Parameters.AddWithValue("@LimitMinutes", intMinutes);
                cmd1.Parameters.AddWithValue("@MaxAttempts", intAttempts);

                object result = cmd1.ExecuteScalar();

                if (Convert.ToInt32(result) <= 0)
                {
                    // Get most recent OTP timestamp for wait time
                    strsql = @"
                    SELECT TOP 1 
                    CAST(OTP_SentDate AS DATETIME) + CAST(OTP_SentTime AS DATETIME) AS LastSent
                    FROM OTP_Master
                    WHERE OTP_ClientCode = @ClientCode
                    AND OTP_Product = @Product
                    AND OTP_Type = @Mode
                    AND CAST(OTP_SentDate AS DATETIME) + CAST(OTP_SentTime AS DATETIME) 
                    >= DATEADD(MINUTE, -@LimitMinutes, GETDATE())
                    ORDER BY OTP_SentDate DESC, OTP_SentTime DESC;";

                    cmd1 = new SqlCommand(strsql, objConnection);
                    cmd1.Parameters.AddWithValue("@ClientCode", clientCd.ToUpper());
                    cmd1.Parameters.AddWithValue("@Product", Product);
                    cmd1.Parameters.AddWithValue("@Mode", Mode);
                    cmd1.Parameters.AddWithValue("@LimitMinutes", intMinutes);

                    object lastSentObj = cmd1.ExecuteScalar();

                    if (lastSentObj != null && DateTime.TryParse(lastSentObj.ToString(), out DateTime lastSent))
                    {
                        DateTime nextAllowed = lastSent.AddMinutes(intMinutes);
                        TimeSpan remaining = nextAllowed - DateTime.Now;

                        if (remaining.TotalSeconds > 0)
                        {
                            int minutes = (int)remaining.TotalMinutes;
                            int seconds = remaining.Seconds;
                            string waitTimeMsg = $"Too many OTP attempts. Try again after {minutes} minute(s) and {seconds} second(s).";

                            return (Status: "N", Message: waitTimeMsg);
                        }
                    }

                    return (Status: "N", Message: "Too many OTP attempts. Try after some time.");
                }

                return (Status: "Y", Message: "");
            }
            catch (Exception ex)
            {
                return (Status: "N", Message: "Error : " + ex.Message);
            }
        }

        public string GenerateRefreshToken(string UserId, string LoginAs, string Role, int ExpiryTime)
        {
            string Strsql = "";
            if (!fnchkTable("RefreshTokens"))
            {
                Strsql = " CREATE TABLE RefreshTokens(" +
                         " [Id] [int] IDENTITY(1,1) NOT NULL, " +
                         " [UserCode] [varchar](16) NOT NULL, " +
                         " [UserType] [char](1) NOT NULL, " +
                         " [Role] [varchar](20) NOT NULL, " +
                         " [Token] [nvarchar](500) NOT NULL, " +
                         " [ExpiryDate] [datetime] NOT NULL, " +
                         " [IsRevoked] [bit] NOT NULL, " +
                         " [Filler1] [char](1) NOT NULL, " +
                         " [Filler2] [char](1) NOT NULL, " +
                         " [Filler3] [char](1) NOT NULL, " +
                         " [NFiller1] [numeric](18, 0) NOT NULL, " +
                         " [NFiller2] [numeric](18, 0) NOT NULL, " +
                         " [NFiller3] [numeric](18, 0) NOT NULL, " +
                         " CONSTRAINT [PK_RefreshTokens] PRIMARY KEY CLUSTERED " +
                         " ( " +
                         "    [Id] ASC" +
                         ")" +
                         ")";
                ExecuteSQL(Strsql);

                Strsql = "CREATE NONCLUSTERED INDEX indx1_RefreshTokens ON RefreshTokens(UserCode, UserType); ";
                ExecuteSQL(Strsql);
            }

            var randomNumber = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(randomNumber);
                string strRefToken = Convert.ToBase64String(randomNumber);

                Strsql = "update RefreshTokens set IsRevoked = 1 where UserCode = '" + UserId + "' and UserType = '" + LoginAs + "' and IsRevoked = 0";
                ExecuteSQL(Strsql);

                Strsql = "Insert into RefreshTokens values('" + UserId + "', '" + LoginAs + "', '" + Role + "', '" + strRefToken + "', DATEADD(minute, " + ExpiryTime + ", GETDATE()), '0', '', '', '', 0, 0, 0)";
                ExecuteSQL(Strsql);

                return strRefToken;
            }
        }

