        public async Task<(string message, VersionData data)> VersionAPI(string urlWithParams, string strParamName)
        {
            string message = "";
            VersionData data = new VersionData();
            var client = new HttpClient();

            HttpResponseMessage response;
            try
            {
                response = await client.GetAsync(urlWithParams);
            }
            catch (Exception ex)
            {
                message = $"Request failed: {ex.Message}";
                return (message, data);
            }

            if (!response.IsSuccessStatusCode)
            {
                message = $"Error: {response.StatusCode}";
                return (message, data);
            }

            var responseBody = await response.Content.ReadAsStringAsync();
            var wrapper = JsonConvert.DeserializeObject<VersionReponse<VersionData>>(responseBody);

            if (wrapper?.Data == null)
            {
                message = "No data returned from API";
                return (message, data);
            }

            return (message, wrapper.Data);
        }

        public string ExecuteVersion(string strParamName, string ApplicationName, DataTable dtRes, VersionInfo versionInfo, VersionData VersionRes, SqlConnection sqlCon = null)
        {
            string strsql = "";
            bool blnSkip = versionInfo.LocalSPFileDate > versionInfo.WebSPFileDate.AddMinutes(1);
            if ((versionInfo.LocalSPFileDate - versionInfo.WebSPFileDate).Duration() < TimeSpan.FromMinutes(1))
            {
                if ((versionInfo.WebDBDate - versionInfo.ParamDBDate).Duration() > TimeSpan.FromMinutes(1))
                {
                    if (VersionRes.DBDetails != null)
                    {
                        var db = new DataContext();
                        //SqlConnection sqlCon = new SqlConnection(strConnection);
                        if (sqlCon == null)
                        {
                            sqlCon = new SqlConnection(db.Database.GetDbConnection().ConnectionString);
                        }
                        if (sqlCon.State == ConnectionState.Closed)
                        {
                            sqlCon.Open();
                        }
                        foreach (var dbDetail in VersionRes.DBDetails)
                        {
                            if (!string.IsNullOrEmpty(dbDetail.Query))
                            {
                                var statements = dbDetail.Query.Split(';').Select(s => s.Trim()).Where(s => !string.IsNullOrWhiteSpace(s)).ToList();

                                foreach (var statement in statements)
                                {
                                    try
                                    {
                                        using SqlCommand command = new SqlCommand(statement, sqlCon);
                                        command.ExecuteNonQuery();
                                    }
                                    catch (Exception ex)
                                    {
                                        return JsonConvert.SerializeObject(new CrossNetCommonModel { success = false, message = ApplicationName + " DB Error : " + ex.Message + " Last Used Query : " + statement, data = null, datarows = null }, Newtonsoft.Json.Formatting.Indented);
                                    }
                                }
                            }
                        }

                        if (Convert.ToInt16(fnFireQueryTradeWeb("webparameter", "count(0)", "sp_parmcd", strParamName + "DBDT", true, sqlCon)) > 0)
                        {
                            strsql = "update webparameter set sp_sysvalue = '" + versionInfo.WebDBDate.ToString("yyyyMMddHHmmss") + "' where sp_parmcd='" + strParamName + "DBDT'";
                        }
                        else
                        {
                            strsql = "Insert into Webparameter values('" + strParamName + "DBDT', '" + strParamName + " Database Date', '" + versionInfo.WebDBDate.ToString("yyyyMMddHHmmss") + "')";
                        }
                        ExecuteSQL(strsql, sqlCon);
                    }
                }

                if ((versionInfo.ParamSPFileDate - versionInfo.WebSPFileDate).Duration() > TimeSpan.FromMinutes(1))
                {
                    try
                    {
                        CheckSPNew(strParamName, sqlCon);
                    }
                    catch (Exception ex)
                    {
                        return JsonConvert.SerializeObject(new CrossNetCommonModel { success = false, message = ApplicationName + " SP Error : " + ex.Message, data = null, datarows = null }, Newtonsoft.Json.Formatting.Indented);
                    }
                }
            }
            else
            {
                if (!blnSkip)
                {
                    string strMessage = "This version requires an update to the database component. (Release Date: " + versionInfo.WebSPFileDate.ToString("dd/MM/yyyy") + ")" + (versionInfo.WebSPFileStatus == "M" ? "Please Update" : "");
                    dtRes.Rows.Add(ApplicationName + "WebSP", versionInfo.WebSPFileStatus, strMessage);
                    DataSet dsResTemp = new DataSet();
                    dsResTemp.Tables.Add(dtRes);

                    return JsonConvert.SerializeObject(new CrossNetCommonModel { success = false, message = strMessage, data = dsResTemp, datarows = new List<string> { "1" } }, Newtonsoft.Json.Formatting.Indented);
                }
            }

            return "";
        }

        public (bool blnSubBrokerAMCreceived, string strMessage, bool blnContWithoutKey) SubBrokerAMCreceived()
        {
            List<string> arrData = new List<string>();
            double dblCTotal = 0;
            bool mfnSubBrokerAMCreceived = false;
            string strMessage = "";
            bool blnContWithoutKey = true;

            string strCompanyCode = OpenDataTable("select min(em_cd) from Entity_master").Rows[0][0].ToString().Trim();
            string strCompanyName = fnFireQuery("Entity_master", "em_Name", "em_cd", strCompanyCode, true);

            string strSql = "select st_KeyVal from sysTable Where st_KeyVal Like '%" + strCompanyName + "%'";
            DataTable dtTemp = OpenDataTable(strSql);

            if (dtTemp.Rows.Count > 0)
            {
                arrData = dtTemp.Rows[0]["st_KeyVal"].ToString().Trim().Split('-').ToList();

                for (int intcnt = 0; intcnt < strCompanyName.Length; intcnt++)
                {
                    dblCTotal += (strCompanyName[intcnt] * (intcnt + 1));
                }

                blnContWithoutKey = true;
                string gStrDbToday = DateTime.Now.ToString("yyyyMMdd");
                if (arrData.Count > 3)
                {
                    string strValidUpdt = A2N(arrData[arrData.Count - 1].Substring(0, 1)).ToString();

                    if (string.Compare(gStrDbToday, strValidUpdt, StringComparison.Ordinal) > 0)
                    {
                        int lngDatediff = (int)(DateTime.ParseExact(gStrDbToday, "yyyyMMdd", null)
                            - DateTime.ParseExact(strValidUpdt, "yyyyMMdd", null)).TotalDays;

                        if (lngDatediff <= 5)
                        {
                            strMessage = $"The Licence to use TradePlus has expired on {strValidUpdt} " +
                                     $"and remaining grace period is only {5 - lngDatediff} days";
                        }
                        else
                        {
                            blnContWithoutKey = false;
                            strMessage = $"Your Licence to use TradePlus has expired on {strValidUpdt}";
                        }
                    }
                    else if (gStrDbToday == strValidUpdt)
                    {
                        strMessage = $"Your Licence to use TradePlus will expired on {strValidUpdt}";
                    }
                    else
                    {
                        if (A2N(arrData[1]) == dblCTotal)
                        {
                            mfnSubBrokerAMCreceived = true;
                        }
                        else
                        {
                            strMessage = $"This version of TradePlus requires a Licence Key...";
                        }
                    }
                }
            }

            return (mfnSubBrokerAMCreceived, strMessage, blnContWithoutKey);
        }

        public (bool blnContWithoutKey, string strMessage, List<string> arrKey) chkAMCReceived()
        {
            /*var (mfnSubBrokerAMCreceived, strMessage, blnContWithoutKey) = SubBrokerAMCreceived();

            if (mfnSubBrokerAMCreceived)
            {
                return (blnContWithoutKey, "", new List<string>());
            }

            if (!blnContWithoutKey)
            {
                return (blnContWithoutKey, strMessage, new List<string>());
            }*/

            List<string> arrData = new List<string>();
            List<string> arrKey = new List<string>();
            string strValue = fnFireQueryTradeWeb("sysSetting", "sys_Value", "'A'", "A", true);
            string strTempDate;
            string strReleasedDt = "";

            if (strValue != "")
            {
                arrData = strValue.Split('-').ToList();

                for (int intcnt = 0; intcnt < arrData.Count - 1; intcnt++)
                {
                    arrKey.Add(A2N(arrData[intcnt]).ToString());
                }

                if (arrData.Count > 1)
                {
                    string last = arrData[arrData.Count - 1];
                    string modified = last.Substring(0, 1) + A2N(last.Substring(1));
                    arrKey.Add(modified);
                }
            }
            else
            {
                arrKey.Add("U20090630");
            }

            string strValidUpdt = arrKey[arrKey.Count - 1].Substring(1);
            DateTime parsedDate;
            if (DateTime.TryParseExact(strValidUpdt, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out parsedDate))
            {
                strValidUpdt = parsedDate.ToString("yyyyMMdd");
            }
            else
            {
                strValidUpdt = "20090630";
            }
            var blnContWithoutKey = true;
            var strMessage = "";

            if (string.Compare(DateTime.Now.ToString("yyyyMMdd"), strValidUpdt, StringComparison.Ordinal) > 0)
            {
                if (arrKey[arrKey.Count - 1].StartsWith("L"))
                {
                    strTempDate = strReleasedDt;

                    if (strTempDate.Contains("/"))
                    {
                        int pos = strTempDate.IndexOf("/");
                        if (pos >= 2 && strTempDate.Length >= pos - 2 + 10)
                        {
                            strTempDate = strTempDate.Substring(pos - 2, 10);
                        }
                    }

                    DateTime tempDate;
                    if (DateTime.TryParse(strTempDate, out tempDate))
                    {
                        strTempDate = tempDate.ToString("yyyyMMdd");

                        if (string.Compare(strTempDate, strValidUpdt, StringComparison.Ordinal) > 0)
                        {
                            blnContWithoutKey = false;
                            strMessage = $"Your Licence to use TradePlus has expired on {DateTime.ParseExact(strValidUpdt, "yyyyMMdd", null):dd/MM/yyyy}";
                            //blnFrmKey = true;
                        }
                    }
                }
                else
                {
                    // Parse dates (both are yyyyMMdd strings)
                    DateTime validUpdt = DateTime.ParseExact(strValidUpdt, "yyyyMMdd", null);
                    DateTime dbToday = DateTime.Now;

                    // Calculate date difference in days
                    int lngDatediff = (dbToday - validUpdt).Days;

                    if (lngDatediff <= 5)
                    {
                        strMessage = $"The Licence to use TradePlus has expired on {validUpdt:dd/MM/yyyy} " +
                                 $"and remaining grace period is only {5 - lngDatediff} days {Environment.NewLine}";
                        //blnFrmKey = true;
                    }
                    else
                    {
                        blnContWithoutKey = false;
                        strMessage = $"Your Licence to use TradePlus has expired on {validUpdt:dd/MM/yyyy}";
                        //blnFrmKey = true;
                    }
                }
            }
            else if (DateTime.Now.ToString("yyyyMMdd") == strValidUpdt)
            {
                strMessage = "Your Licence to use TradePlus will expired on " + ctod(strValidUpdt);
            }

            return (blnContWithoutKey, strMessage, arrKey);
        }

        public static double A2N(string strAlp)
        {
            double intRtn = 0;
            double mult = 1;

            try
            {
                strAlp = strAlp.TrimEnd();

                while (strAlp.Length > 0)
                {
                    string stra = strAlp.Substring(strAlp.Length - 1, 1);  // last char
                    intRtn += (stra[0] - 65) * mult;  // Asc(stra) - 65
                    mult *= 26;
                    strAlp = strAlp.Substring(0, strAlp.Length - 1).TrimEnd(); // remove last char
                }
            }
            catch (Exception ex)
            {
                // Equivalent of MsgBox + ErrMessage
                Console.WriteLine($"{ex.Message} [Number: {ex.HResult}]");
                // If you have a custom error logger, call it here
                // ErrMessage.ErrMsg(ex, ex.HResult, ex.Message, "A2N", "Trade_plus");
            }

            return intRtn;
        }

        public string GetUserAccess(string specialRights)
        {
            string strTemp = specialRights;
            strTemp = (strTemp.Length < 7) ? strTemp.PadRight(7, '0') : strTemp;
            if (strTemp.Length == 7)
            {
                strTemp += "1";
            }

            if (strTemp.Length == 8)
            {
                strTemp += "1";
            }

            string ch = strTemp.Length >= 7 ? strTemp.Substring(6, 1) : "";
            if ("01B".Contains(ch))
            {
                return "HO";
            }
            else if (ch == "N")
            {
                return "Branch";
            }
            else
            {
                return "HO";
            }
        }

        public byte[] Base64UrlDecode(string base64Url)
        {
            // Convert from Base64Url to Base64
            string padded = base64Url.Replace('-', '+').Replace('_', '/');
            switch (padded.Length % 4)
            {
                case 2: padded += "=="; break;
                case 3: padded += "="; break;
            }
            return Convert.FromBase64String(padded);
        }

        public LoginRole GetLoginRole(string loginAs, string product)
        {
            string role = "";
            bool blnOffline = Convert.ToInt16(fnFireQueryTradeWeb("Information_Schema.Columns", "count(*)", "Table_Name='client_master' and Column_Name", "cm_companycode", true)) > 0;
            //string autResp = "";
            //var (blnContinueWithouKey, licMsg, arrKey) = objUtility.chkAMCReceived();
            string strLicMessage = "";
            string strHO = "N";
            string strNet = "N";
            string strWeb = "N";
            bool blnConWithoutKey = false;
            if (blnOffline)
            {
                if (mfnGetSysSplFeatureDP("TBO"))
                {
                    if (product == "C" || product == "E")
                    {
                        strWeb = "Y";
                    }
                }
            }
            else
            {
                bool blnInvalidDB = false;
                DataTable dtDB = new DataTable();
                if (product == "C" || product == "E")
                {
                    dtDB = OpenDataTable("select count(*) from sysobjects with (nolock) where name='Trxdetail' and xType='U'");
                    if (dtDB.Rows.Count > 0)
                    {
                        if (Convert.ToInt16(dtDB.Rows[0][0].ToString()) == 0)
                        {
                            blnInvalidDB = true;
                        }
                    }

                    string strColLen = product == "C" ? "16" : "8";
                    dtDB = OpenDataTable("select b.length from Sysobjects a,Syscolumns b,Systypes c where a.id = b.id and a.name = 'Trxdetail' and b.name = 'td_ac_code' and b.xusertype = c.xtype");
                    if (dtDB.Rows.Count > 0)
                    {
                        if (dtDB.Rows[0][0].ToString() != strColLen)
                        {
                            blnInvalidDB = true;
                        }
                    }

                    if (blnInvalidDB)
                    {
                        return new LoginRole { Role = "", Message = "Invalid " + (product == "C" ? "Cross" : "Estro") + " Database" };
                        //return returnJson.ConvertDataIntoJson(false, (int)HttpStatusCode.OK, "Invalid " + product == "C" ? "Cross" : "Estro" + " Database", returnDt, "");
                    }
                }

                var (blnContinueWithouKey, licMsg, arrKey) = chkAMCReceived();
                strLicMessage = licMsg;
                blnConWithoutKey = blnContinueWithouKey;
                foreach (var lickey in arrKey)
                {
                    if (product == "T")
                    {
                        if (lickey.StartsWith("10"))
                        {
                            if (lickey.Substring(2, 1) == "1")
                            {
                                strNet = "Y";
                                //role = "Branch";
                            }
                            if (lickey.Substring(3, 1) == "1")
                            {
                                strWeb = "Y";
                                //role = loginAs == "M" ? "TradeMobile" : "Admin";
                            }
                            strHO = "Y";
                            //role = "Branch";
                            break;
                        }
                    }
                    else if (product == "C")
                    {
                        if (lickey.StartsWith("55"))
                        {
                            if (lickey.Substring(2, 1) == "1")
                            {
                                strNet = "Y";
                                //role = "CrossNet";
                            }
                            if (lickey.Substring(3, 1) == "1")
                            {
                                strWeb = "Y";
                                //role = "CrossWeb";
                            }
                            strHO = "Y";
                            //role = "CrossNet";
                            break;
                        }
                    }
                    else if (product == "E")
                    {
                        if (lickey.StartsWith("56"))
                        {
                            if (lickey.Substring(2, 1) == "1")
                            {
                                strNet = "Y";
                                //role = "EstroNet";
                            }
                            if (lickey.Substring(3, 1) == "1")
                            {
                                strWeb = "Y";
                                //role = "EstroWeb";
                            }
                            strHO = "Y";
                            //role = "EstroNet";
                            break;
                        }
                    }
                }
            }

            if (product == "T")
            {
                if (loginAs == "C" && strWeb == "Y")
                {
                    role = "Admin";
                }
                else if (loginAs == "B" && (strNet == "Y" || strHO == "Y"))
                {
                    role = "Branch";
                }
                else if (loginAs == "M" && mfnGetSysSplFeature("TMB"))
                {
                    role = "TradeMobile";
                }
            }
            else if (product == "C")
            {
                if (loginAs == "C" && strWeb == "Y")
                {
                    role = "CrossWeb";
                }
                else if (loginAs == "B" && strNet == "Y")
                {
                    role = "CrossNet";
                }
            }
            else if (product == "E")
            {
                if (loginAs == "C" && strWeb == "Y")
                {
                    role = "EstroWeb";
                }
                else if (loginAs == "B" && strNet == "Y")
                {
                    role = "EstroNet";
                }
            }

            return new LoginRole { Role = role, HO = strHO, Net = strNet, Web = strWeb, Offline = blnOffline, Message = "", LicMsg = strLicMessage, ContinueWithoutKey = blnConWithoutKey };
        }

        public void prCommonInsert(string strMaster, string strTable, string strDpid, string strKeyfield, string strKeyName, string strKeyValue, string strField, string strFieldDesc, string strOldValue, string strNewValue, string strComputername, string strmkrid, string strmkrdt, string strMkrtm, string strMkridOld, string strMkrdtOld, string strMkrtmOld)
        {
            string connectionString = GetConnectionStr();
            string strSql = @"
            INSERT INTO Common_audit
            (
                ca_master,
                ca_table,
                ca_dpid,
                ca_keyfield,
                ca_keyname,
                ca_keyvalue,
                ca_field,
                ca_fielddescription,
                ca_oldvalue,
                ca_newvalue,
                ca_computername,
                mkrid,
                mkrdt,
                mkrtm,
                mkridold,
                mkrdtold,
                mkrtmold
            )
            VALUES
            (
                @ca_master,
                @ca_table,
                @ca_dpid,
                @ca_keyfield,
                @ca_keyname,
                @ca_keyvalue,
                @ca_field,
                @ca_fielddescription,
                @ca_oldvalue,
                @ca_newvalue,
                @ca_computername,
                @mkrid,
                @mkrdt,
                @mkrtm,
                @mkridold,
                @mkrdtold,
                @mkrtmold
            )";

            using (SqlConnection conn = new SqlConnection(connectionString))
            {
                using (SqlCommand cmd = new SqlCommand(strSql, conn))
                {
                    cmd.Parameters.AddWithValue("@ca_master", strMaster ?? string.Empty);
                    cmd.Parameters.AddWithValue("@ca_table", strTable ?? string.Empty);
                    cmd.Parameters.AddWithValue("@ca_dpid", strDpid ?? string.Empty);
                    cmd.Parameters.AddWithValue("@ca_keyfield", strKeyfield ?? string.Empty);
                    cmd.Parameters.AddWithValue("@ca_keyname", strKeyName ?? string.Empty);
                    cmd.Parameters.AddWithValue("@ca_keyvalue", strKeyValue?.Trim() ?? string.Empty);
                    cmd.Parameters.AddWithValue("@ca_field", strField ?? string.Empty);
                    cmd.Parameters.AddWithValue("@ca_fielddescription", strFieldDesc ?? string.Empty);
                    cmd.Parameters.AddWithValue("@ca_oldvalue", (strOldValue ?? string.Empty).Replace("'", "").Trim());
                    cmd.Parameters.AddWithValue("@ca_newvalue", (strNewValue ?? string.Empty).Replace("'", "").Trim());
                    cmd.Parameters.AddWithValue("@ca_computername", strComputername ?? string.Empty);
                    cmd.Parameters.AddWithValue("@mkrid", strmkrid?.Trim() ?? string.Empty);
                    cmd.Parameters.AddWithValue("@mkrdt", strmkrdt?.Trim() ?? string.Empty);
                    cmd.Parameters.AddWithValue("@mkrtm", strMkrtm?.Trim() ?? string.Empty);
                    cmd.Parameters.AddWithValue("@mkridold", strMkridOld?.Trim() ?? string.Empty);
                    cmd.Parameters.AddWithValue("@mkrdtold", strMkrdtOld?.Trim() ?? string.Empty);
                    cmd.Parameters.AddWithValue("@mkrtmold", strMkrtmOld?.Trim() ?? string.Empty);

                    if (conn.State == ConnectionState.Closed)
                    {
                        conn.Open();
                    }

                    cmd.ExecuteNonQuery();
                }
            }
        }

