        public string ExtractSignature(string xml)
        {
            var doc = XDocument.Parse(xml);

            XNamespace tempuri = "http://tempuri.org/";

            return doc
                .Descendants(tempuri + "GetsignatureResult")
                .FirstOrDefault()
                ?.Value;
        }

        public void TypstCreateCompanyLogo(string baseDir)
        {
            string strAssetsPath = Path.Combine(baseDir, "Assets");

            if (!Directory.Exists(strAssetsPath))
                Directory.CreateDirectory(strAssetsPath);

            string logofilePath = Path.Combine(baseDir, "Assets", "CompanyLogo.png");

            if (!File.Exists(logofilePath))
            {
                string strsql = "Select img_code, img_logo logo from Images with (nolock) where img_desc = 'Company Logo' and img_logo is not null order by img_code";
                DataTable dtLogo = OpenDataTable(strsql);
                if (dtLogo.Rows.Count > 0)
                {
                    byte[] logoBytes = (byte[])dtLogo.Rows[0]["logo"];
                    try
                    {
                        using var ms = new MemoryStream(logoBytes);
                        using var image = System.Drawing.Image.FromStream(ms);
                        image.Save(logofilePath, System.Drawing.Imaging.ImageFormat.Png);  // Save as PNG
                    }
                    catch
                    {
                        File.WriteAllBytes(logofilePath, logoBytes); // just dump it
                    }
                }
            }
        }

        public string GetCompanyHeaderImageAsync(string baseDir, string companyCode)
        {
            if (string.IsNullOrEmpty(companyCode))
                return string.Empty;

            int asciiValue = Convert.ToInt32(companyCode[0]);
            string imgCode = "0" + (asciiValue - 64);

            DataTable dtHdrImg = OpenDataTable(
                $"SELECT * FROM Images (NOLOCK) WHERE img_code = '{imgCode}'AND img_desc = 'Combined Contract'");

            if (dtHdrImg.Rows.Count == 0)
                return string.Empty;

            string headerImagePath = Path.Combine(baseDir, "CompanyHeaderLogo.png");

            if (!File.Exists(headerImagePath))
            {
                byte[] logoBytes = (byte[])dtHdrImg.Rows[0]["img_logo"];

                try
                {
                    using var ms = new MemoryStream(logoBytes);
                    using var image = System.Drawing.Image.FromStream(ms);
                    image.Save(headerImagePath, System.Drawing.Imaging.ImageFormat.Png);
                }
                catch
                {
                    File.WriteAllBytes(headerImagePath, logoBytes);
                }
            }
            return headerImagePath;
        }

        public string DecryptAES(string encryptedBase64, string strAESKey)
        {
            string keyString = strAESKey;

            if (string.IsNullOrEmpty(keyString))
                throw new Exception("AES key not configured.");

            byte[] key = Encoding.UTF8.GetBytes(keyString);

            if (!(key.Length == 16 || key.Length == 24 || key.Length == 32))
                throw new Exception("Invalid AES key length.");

            byte[] fullCipher = Convert.FromBase64String(encryptedBase64);

            using (Aes aes = Aes.Create())
            {
                aes.Key = key;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                byte[] iv = new byte[16];
                byte[] cipherText = new byte[fullCipher.Length - 16];

                global::System.Buffer.BlockCopy(fullCipher, 0, iv, 0, 16);
                global::System.Buffer.BlockCopy(fullCipher, 16, cipherText, 0, cipherText.Length);

                aes.IV = iv;

                using (MemoryStream ms = new MemoryStream(cipherText))
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Read))
                using (StreamReader sr = new StreamReader(cs))
                {
                    return sr.ReadToEnd();
                }
            }
        }

        public string FixBase64(string base64)
        {
            if (string.IsNullOrEmpty(base64)) return base64;

            string fixed64 = base64
                .Replace(' ', '+')
                .Replace('-', '+')
                .Replace('_', '/');

            int padding = fixed64.Length % 4;
            if (padding == 2) fixed64 += "==";
            else if (padding == 3) fixed64 += "=";

            return fixed64;
        }

        public (string strParam, string strMessage) CheckeIPAddressLogin(string UserID, string IPAddress)
        {
            #region Check IP address for Login
            if (fnchkTable("Web_IP"))
            {
                string chkParamIP = GetSysParmSt("IPBLOCKING", "");

                if (chkParamIP != "D" && chkParamIP != "")
                {
                    DataSet ds = new DataSet();
                    string strRemoteIP = IPAddress;

                    int lastDot = strRemoteIP.LastIndexOf('.');

                    string ip1 = strRemoteIP.Trim();
                    string ip2 = "";
                    string ip3 = "";

                    if (lastDot > 0)
                    {
                        ip2 = strRemoteIP.Substring(0, lastDot) + ".*";

                        int secondLastDot = strRemoteIP.LastIndexOf('.', lastDot - 1);

                        if (secondLastDot > 0)
                        {
                            ip3 = strRemoteIP.Substring(0, secondLastDot) + ".*";
                        }
                    }

                    ds = OpenDataSet("Select * From web_ip Where web_access = 'Y'");
                    if (ds.Tables[0].Rows.Count > 0)
                    {
                        int Len = Strings.InStrRev(strRemoteIP, ".", strRemoteIP.Length, CompareMethod.Text);

                        string strsql = "select * from Web_IP where (web_userid = '" + UserID + "' and web_ipfrom = '" + ip1 + "') ";
                        strsql += " OR (web_userid = '" + UserID + "' and web_ipfrom = '" + ip2 + "') ";
                        strsql += " OR (web_userid = '" + UserID + "' and web_ipfrom = '" + ip3 + "') ";
                        strsql += " OR (web_userid = '' and web_ipfrom = '" + ip1 + "') ";
                        strsql += " OR (web_userid = '' and web_ipfrom = '" + ip2 + "') ";
                        strsql += " OR (web_userid = '' and web_ipfrom = '" + ip3 + "') ";

                        DataTable dtIP = new DataTable();
                        dtIP = OpenDataTable(strsql);
                        if (dtIP.Rows.Count > 0)
                        {
                            if (dtIP.Rows[0]["web_access"].ToString().Trim() == "N")
                            {
                                string confrmIpMsg = WebBasedBlocking(UserID, strRemoteIP, chkParamIP, "N", Convert.ToInt32(dtIP.Rows[0]["web_srno"].ToString()));
                                if (confrmIpMsg != "")
                                {
                                    return (chkParamIP, "You Are Trying To Login From Unauthorised Location / System");
                                }
                            }
                        }
                        else
                        {
                            string confrmIpMsg = WebBasedBlocking(UserID, strRemoteIP, chkParamIP, "");
                            if (confrmIpMsg != "")
                            {
                                return (chkParamIP, "You Are Trying To Login From Unauthorised Location / System");
                            }
                        }
                    }
                    else
                    {
                        if (chkParamIP == "B")
                        {
                            return (chkParamIP, "You Are Trying To Login From Unauthorised Location / System");
                        }
                    }
                }
            }
            #endregion
            return ("", "");
        }

        public string WebBasedBlocking(string userId, string ipAddress, string strIPMode, string strAcccess, int websrno = 0)
        {
            string strsql = "";
            if (strIPMode == "C")
            {
                return "You Are Trying To Login From Unauthorised Location / System";
            }
            else if (strIPMode == "P")
            {
                if (strAcccess != "N")
                {
                    strsql = " insert into web_ip(web_userid,web_ipfrom,web_access,web_remark,Mkrdt) ";
                    strsql = strsql + " values ('" + userId.ToUpper() + "','" + ipAddress + "','Y','','" + DateTime.Now.ToString("yyyyMMdd") + "')";
                }
                else
                {
                    strsql = " update web_ip set web_access = 'Y' , Mkrdt='" + DateTime.Now.ToString("yyyyMMdd") + "' ";
                    strsql = strsql + " where web_srno = " + websrno;
                }
                ExecuteSQL(strsql);

                return "";
            }
            else if (strIPMode == "A")
            {
                DataSet DsTemp = new DataSet();
                DsTemp = OpenDataSet("select * From Web_IP Where web_userid= '" + userId.ToUpper() + "' and web_access = 'Y'");
                if (DsTemp.Tables[0].Rows.Count > 0)
                {
                    return "You Are Trying To Login From Unauthorised Location / System";
                }
                else
                {
                    return "";
                }

            }
            else if (strIPMode == "B")
            {
                return "You Are Trying To Login From Unauthorised Location / System";
            }
            else
            {
                return "";
            }
        }

